/* 《天運者》全面重寫 第一批續：夫人非核心文本（diaochan、lvzhi）
 * 載入順序：story*.js → inbox/text 既有檔（sec7_*、history_fix_overrides）→ rewrite_01a–01d → 本檔 → rewrite_01z（最後）。
 * 合併方式：只覆寫既有字串（物件逐鍵、陣列逐索引），不新增、不刪除鍵，數值與效果欄位不動。
 * Node：require 後得 {D, apply(GD)}。 */
(function(root){
const D={"personal":{"diaochan":{"陌生":[[null,"貂蟬倚在石欄邊，衣襟故意鬆了一寸，見你走近，臉上立刻換上一副挑不出毛病的溫婉笑容，眼睛卻先把你腰間的印綬掃了一遍。"],[null,"夜深露重，主公怎麼一個人走到這裡？是來看妾身的，還是來看妾身值多少的？"],[null,"見妳站在風口，怕妳著涼。披上這件外衣。"],[null,"（接過外衣，指尖在你手背上輕輕一劃）主公待女人都這麼體貼？王司徒當年也是這樣，替我披衣、教我跳舞，然後把我送給了董卓。"]],"熟識":[[null,"你路過暖閣，貂蟬獨自坐在燈下補一件被黑霧劃破的舞衣，沒有笑，臉上的脂粉也卸了，眼底一片青黑。"],[null,"（手一抖，針扎進指頭，她把血珠吮掉）主公走路沒聲音的？讓您看見妾身這副不值錢的樣子了。"],[null,"我覺得這樣的妳，比笑著應酬時真。在這裡，妳不用一直演。"],[null,"（盯著你看了很久，冷冷一笑）這話說得好聽。上一個這麼說的人是呂布，他說完，提著方天畫戟去殺了他義父。（把針線放下）留下來喝杯茶吧——我想看看你要什麼。"]],"信賴":[[null,"月光照在貂蟬發紅的眼角上。她喝了半壺酒，第一次說起郿塢裡的那些夜晚。"],[null,"董卓肥得像頭豬，每晚壓在我身上喘氣。我一邊笑，一邊數他還有幾天好活。呂布在屏風後頭看著，眼睛都紅了——他以為我是被逼的。（舉杯）我是。可我也很樂意。主公，你會不會有一天也把我送給下一個人？"],[null,"聽好，貂蟬。這座燈塔的江山，用刀和謀略去打，用不著拿妳去換。"],[null,"（把酒杯捏得發白，忽然笑出了眼淚）你最好說到做到。我這輩子殺人，從來不用自己動手。"]],"親密":[[null,"閣裡點著沉水香，貂蟬為你獨舞一曲。舞到最後，她的外衫已經滑到腳邊，旋身落進你懷裡，雙臂勾住你的脖子，身上燙得像火。"],[null,"這支舞，從前是跳給董卓看、跳給呂布看，跳給滿堂公卿看，跳到他們為我拔刀互砍。今晚，只跳給你一個人。"],[null,"跳得太美了，讓我移不開眼。"],[null,"（一口吹熄燭火，在黑暗裡咬住你的耳垂）那就別移開。今晚你走不了——我不准。"]],"誓約":[[null,"紅紗漫捲，星盤的光落在她盛裝的眉眼間。貂蟬端起合巹酒，笑得比星辰還亮，眼底卻沒有一點淚。"],[null,"我被送過兩次：王允送給董卓，董卓死了，又落到呂布手裡；呂布在白門樓被絞死，我又被當成戰利品。今天是我第一次自己選男人。"],[null,"從今往後，這座城是妳的家，我是妳的歸宿。"],[null,"（一飲而盡，把杯子摔碎在地上）夫君，貂蟬這輩子只屬於你。你要是敢把我送人，我就讓你和收下我的那個人，像董卓和呂布一樣，互相捅死。"]],"talk":{"陌生":["主公若只是想找人排遣寂寞，妾身隨時可以為您舞一曲——舞一曲，換什麼，咱們再談。","這片荒原冷清得很，主公得多保重。您要是死了，妾身又得重新找靠山。","美人計對黑霧怪物沒用，對男人，百試百靈。"],"熟識":["今天營裡的飯菜熱了些，主公有好好吃飯嗎？廚子是我換的，原先那個嘴不乾淨。","跟主公說話時，外頭的黑霧好像也沒那麼可怕——比董卓那張臉好看多了。","這支新編的曲子，等主公忙完，妾身第一個彈給您聽。第二個聽的人，我還沒想好。"],"信賴":["其實……我一直盼著每旬你來的時候。你不來，我就去查你去了哪裡。","主公看我的眼神，跟以前那些男人不一樣。他們看的是我的身子，你看的……也是，但還多看了一眼我的臉。","累了就來。我的暖閣永遠替主公留一盞燈，別的女人的燈，我會想辦法讓它滅了。"],"親密":["主公靠這麼近……是想聽我的心跳，還是想解我的衣帶？","別把公文帶到這裡來，今晚的時辰是妾身的。","拉住我的手。霧再濃，我都找得到你——找得到你，也找得到想搶你的人。"],"誓約":["夫君，昨晚睡得好嗎？（替你繫衣帶，手指在你腰上停了一下）你背上那幾道抓痕，記得別讓別人看見。","只要你在身邊，哪裡都是我的長安。不在，我就把這裡燒了，去找你。","今晚夫君還來嗎？甜湯煮好了。不來，我就去她那裡，把湯親手端給你。"]},"gift":["呀，好精緻！主公特意挑的？替我戴上——戴在你看得見的地方。","主公的心意，妾身收下了。（隨手放進妝匣，跟一堆別人送的東西擺在一起）謝主公。","這個？（拎起來看了一眼，扔給身後的侍女）主公是送錯人了吧？還是想看我笑著說謝謝？"],"low":["主公眼裡現在只剩冰冷的數字和殺伐了嗎？董卓也是這樣，殺人殺到最後，連枕邊的人想什麼都不知道。","連一點溫情都不肯給，這座燈塔跟郿塢那座金牢籠有什麼兩樣？我在牢籠裡，是會找鑰匙的。"],"win":["一曲既終，敵陣自亂～主公，敵將是我灌醉了再讓人割的頭，妾身沒讓您失望吧？","凱旋酒備好了，快回來慶功——晚了，酒就讓別人喝了。"],"lose":["對不起主公……那些怪物根本不聽琴音，牠們不是男人。","衣袖都被抓破了。（把破袖子扯下來扔在你腳邊）主公下次多派點兵護著我——我這張臉，比一座城值錢。"]},"lvzhi":{"陌生":[[null,"你剛巡完外圍防線回帳，案上堆積如山的竹簡與糧冊竟已被朱筆勾得密密麻麻。一名身著玄黑曲裾、腰臀飽滿而脊背挺直的婦人站在案側，眉峰削得像刀，眼角雖有細紋，卻壓得滿帳燭火都低了三分。"],[null,"（頭也不抬，將朱筆擱在硯上）主公，前幾旬放糧太鬆，外營已經養出一批只張嘴不挑土的懶骨頭。本宮替你重寫了軍律：日計工分米，偷懶者鞭二十，再犯者逐出燈塔餵黑霧。"],[null,"呂后連聲招呼都不打，就直接替我批了政令？"],[null,"（抬眸直直釘進你眼裡，唇角扯出一絲冷笑）當年劉季在沛縣當亭長時只知吃酒吹牛，若非我在家拿鞭子盯著奴僕耕織，早餓死在荒年裡。你若連這點狠勁都受不住，這座破塔撐不過三次霧潮。"]],"熟識":[[null,"黑霧挾著暴雨砸下來，外圍糧棚眼看要塌。呂雉竟扯掉外氅，只著一件被雨水浸透的素色中衣站在泥水裡喝令民夫扛袋，濕透的布料緊緊貼在她豐腴的胸乳與腰臀上，她卻連看都懶得看旁人一眼，只把一條皮鞭抽得啪啪作響。"],[null,"這種粗活交給校尉督工便是，妳身子濕透了，何必親自泡在泥裡？"],[null,"（抹去臉上黑泥般的雨水，冷哼一聲）在項羽楚營當了二十八個月人質，連太公都差點被架上砧板烹了，審食其天天替我擦血洗泥，什麼髒活苦活本宮沒熬過？這三百石軍糧若是泡爛了，明早拿誰的命去填？"]],"信賴":[[null,"深夜營帳裡只點著一盞銅燈。呂雉手指停在武將名冊上「韓信」「彭越」四個字之間，指甲把竹簡刮出一道白痕，臉色冷得像長樂宮的鐘室。"],[null,"（嗓音壓得極低，像蛇滑過石階）主公，你對這群手握重兵的武夫太寬厚了。當年彭越在鄭縣哭著求我放他回昌邑，我笑著帶他回洛陽，轉頭就請高祖把他剁成肉醬分賜諸侯——不見血，他們永遠覺得江山是他們打的。"],[null,"（伸手合上名冊，把她冰涼的手指包進掌心）我知道妳當年為了保住大漢不得不當那把刀。在這裡，刀我可以自己握，不用事事推妳出去扛罵名。"],[null,"（指尖猛地一僵，抬眼盯了你許久，忽然低低笑了一聲）你這男人，也不知是真的壓得住群雄，還是膽大包天。罷了……這回本宮先收起刀，看你怎麼治他們。"]],"親密":[[null,"議完密事，你把她拉到胡床邊坐下，親手拔下她鬢間那支沉重的玄玉步搖。滿頭烏髮散落肩頭，她鬆開領口一寸透氣，雪白豐乳隨著深呼吸起伏，那雙向來不怒自威的眸子裡竟浮出一層滾燙的暗色。"],[null,"（嗓音低啞，反手扣住你的手腕按在自己微熱的胸口）主公夜夜這樣待本宮，可想清楚了？我這人佔有慾重得很——當年劉季寵一個戚姬，我忍到他斷氣，就把那賤人剁成肉團丟進茅廁。你要是敢招惹別的狐狸精，本宮下手可不會比當年輕。"],[null,"（指腹摩挲著她微燙的下頜，低頭逼近她的唇）這座城的正宮與共治之位，除了妳，誰坐得穩？"],[null,"（呼吸一滯，雙臂勾住你的頸項將你猛地拽下來，唇角揚起霸道而露骨的笑意）這可是你親口許的。把燈挑亮些——今晚本宮要親眼看著，你這副身子究竟歸誰管。"]],"誓約":[[null,"後宮殿閣已就緒，觸發「呂雉」誓約婚姻劇情。"],[null,"她身著西漢玄纁皇后褘衣，面容冷豔而威儀逼人，腰臀在重錦深衣下勾出成熟而強勢的弧度。她將一枚刻著「同心稱制」的玄玉私印重重壓在你掌心，指尖滾燙。"],[null,"（眸光深沉得像要把你整個人吞進去）前世我嫁給沛縣那個無賴，共了患難，他得了天下卻只記得定陶那賤人的楚舞，害我只能在長樂宮獨自垂簾、連親生兒子都怕我。今生遇上你，敢與我並肩染血、共分山河。"],[null,"（收緊五指握住玉印，將她扣進懷裡重重吻住她微涼的唇）雉，嫁給我。這座歸墟江山，妳我夫妻共掌生殺。"],[null,"（她眼角發紅卻不肯落淚，十指死死扣進你肩背的衣料裡，啞聲道）夫君……這印落下去，就再沒有回頭路。你的天下由本宮替你殺出一片清淨；你的血脈、你的夜，全歸我一人。"],[null,"已與「呂雉」締結婚姻，迎入後宮殿閣！"]],"talk":{"陌生":["慈不掌兵，義不掌財。主公若只會講仁厚，遲早被底下這群餓狼啃得連骨頭都不剩。","西倉的帳冊少了三十石粟米，本宮已經把那名倉吏的指頭夾斷了兩根，他今晚就會招出同黨。","想要在這片黑霧裡活命，先立死規矩，再談恩賞。"],"熟識":["這兩旬城牆起得快了許多——看來把偷懶的民夫抽死兩個示眾，比說十遍大道理管用。","韓信那小子眼神太傲，主公用他打仗可以，千萬別把南北軍的虎符交到他手裡。","民間該輕徭薄賦，休養生息；朝堂上該殺雞儆猴，寸步不讓。這兩件事從不衝突。"],"信賴":["與主公並肩批閱章疏，比當年隔著珠簾聽那群老臣哭喪痛快多了。","前營有幾個刺頭不服管束？不必髒你的手，今夜叫他們來我帳裡喝一碗酒便清淨了。","主公這份殺伐氣度，才配坐這星盤之主。比當年劉季有眼光得多。"],"親密":["章疏批完了？把門閂落下。外頭霧重，過來讓本宮替你解甲——順便暖暖這張冷榻。","在百官面前本宮是鐵腕高后，可熄了燈、解了深衣，我也只是個等了太久的女人。","記住，後宮裡那些年輕丫頭只會哭哭啼啼，唯有本宮能陪你殺人，也能在榻上讓你捨不得下床。"],"誓約":["夫君，今日該斬的貪吏都斬了，帳也平了。剩下的長夜，歸咱們夫妻二人。","你只管帶兵去踏平四方，後方敢生二心的人，本宮替你一個一個做成肉醬。","這座長安城，從前姓劉也姓呂；如今，只姓你我夫妻。"]},"gift":["成色極佳，這才配得上椒房殿的份量。（指尖拂過你的手背）夫……主公這回挑得甚合我意。","尚可，讓宮婢收進庫房記檔吧。","刀槍劍戟是武夫拿來賣命的粗物，本宮要的是印信與珠玉，拿這破鐵來敷衍誰？"],"low":["優柔寡斷、婦人之仁！你再這樣縱容底下那群武夫，這座燈塔不用黑霧來攻，自己就會從裡頭爛穿！","既管不住前朝也鎮不住後宮，主公不如早早退居深殿飲酒作樂，讓本宮臨朝稱制便是！"],"win":["順我者昌，逆我者亡！把敵將的首級醃起來掛在城門，讓周邊那些軍閥看清楚誰才是主人！","敵軍已潰，立刻派人清點地塊、糧倉與丁口，一粒米也不許落進私囊！"],"lose":["一群酒囊飯袋！連這點陣線都守不住，立刻撤回來，領頭逃跑的校尉今晚斬首示眾！","暫退一步又何妨？當年滎陽、彭城敗得比這更慘，最後坐擁天下的還不是我們！","夫君來得正好，本宮剛把各倉虛報的帳目勾出來。門閂上了，今夜不談斬誰，只談咱們夫妻。","世人罵我毒婦、怕我如怕厲鬼，唯獨你敢在深夜解我衣帶、說本宮辛苦了。夫君，這輩子你休想逃出椒房殿。","誰敢在背後算計你，不必等律法審問，本宮直接讓她斷手斷腳、死無全屍。","糧倉、人事與內廷耳目全在本宮手裡攥著，夫君只管放心去打仗，後方漏不出一滴水。","數旬不進椒房殿……怎麼，外頭那些只會搖腰獻媚的年輕賤婢，真比本宮更能伺候你？","聽說夫君昨夜宿在別殿，天亮才走？（慢條斯理地摩挲著茶盞，眼底冷光如刀）無妨，本宮很大度——只是那位妹妹的月例與炭火，明早該重新核定核定了。"],"like":null,"hate":null}},"gen":{"diaochan":{"meet":["妾身以為白門樓那一天，舞完最後一曲就塵歸塵了，沒想到被這星光扯到這裡。","這地方荒得發冷。妾身先看看主公有多少本事——值不值得我留下來。"],"tide2":"風都重了。兩旬之內霧潮就到，妾身先把首飾收好，免得到時候逃命來不及。","tide1":"霧把星星都遮住了……主公，守住這裡。妾身不想再換一個主子。","tideNow":"妾身用琴聲穩住軍心——將軍們，誰活著回來，今晚妾身親手斟酒。","tideWin":"燈塔還在，主公也還在。（鬆了口氣，又笑起來）今晚該辦場宴了，妾身跳舞。","tideLose":"燈塔在哀鳴……防線垮了！主公，往哪裡逃？帶上我，別丟下我——","lowDur":"星盤的光不能在這裡滅！滅了，我這張臉在黑霧裡值不了一文錢。","stage":"城裡有煙火氣了。有人氣的地方，就有男人；有男人，就有妾身用得上的東西。","eve":"壯行酒備好了。明天那些畫皮妖物最好別碰上我——碰上了，我教牠們什麼叫連環。","win":"萬家燈火重燃……主公，長安奪回來了！（笑著倒進你懷裡）這一次，天下是你的，你是我的。","lose":"主公……若有來世，別再讓我遇見這麼冷的地方，也別再讓我遇見把我當禮物的男人。"},"lvzhi":{"meet":["漢高后呂雉在此。你便是這座歸墟之主？眉眼間倒有幾分狠勁，沒讓我白走這一遭。","打天下靠刀劍，守天下靠鐵腕與酷法。內政與後宮這些髒活，交給本宮便是。"],"tide2":"兩旬之內霧潮必至。糧草、木石與民夫全由本宮統一調撥，誰敢藏私拖延，就地斬首。","tide1":"兵甲已齊，糧倉已封。明日黑霧壓境，只許死戰向前，敢後退半步者，本宮親手送他上路。","tideNow":"全軍聽令！凡臨陣退縮者立斬，斬殺妖物者重賞千錢！別讓本宮看輕了你們！","tideWin":"哼，本就該是這個結果。立刻清點傷亡與戰利，明早照常開工築城，不許鬆懈。","tideLose":"一群廢物！連外牆都守不住！親衛護駕退入內城，這筆帳等霧散了本宮挨個算！","lowDur":"燈塔絕不能塌！把預備隊和民夫全押上城頭，死也要把核心給我釘死在原地！","stage":"城池總算有了幾分未央長樂的氣象。這般規模，才配得上本宮與你共治天下。","eve":"長安乃大漢故都，豈容一群畫皮妖孽佔著未央宮址？明日一戰，把牠們連皮帶骨碾成泥！","win":"長安重歸正統！從今往後，這片歸墟的律法、生殺與榮辱，全由你我夫妻說了算！","lose":"本宮熬過了楚營、熬死了劉季，好不容易再掌乾坤，竟會折在這片黑霧裡……我不甘心！"}},"harem":{"diaochan":{"ev":[{"t":"笑裡藏針","d":"茶會上誇 {m} 妝容清雅，轉頭就對侍女說她「素得像守寡」，話傳得滿宮都是。","c":[["私下點破她的心思，笑著讓她收斂",null],["順著她的話誇她最美，當作沒聽見",null]]},{"t":"帳目挑刺","d":"拿著花銷單當眾指出 {m} 多領了三匹絲綢，眼睛卻一直往你這邊瞟。","c":[["交給她全權核對並誇她精明",null],["各打五十大板，再補禮物平息",null]]},{"t":"截人","d":"得知你今晚原定去 {m} 那裡，她半路「崴了腳」，衣衫半褪倒在你經過的迴廊上。","c":[["順勢抱她回暖閣留宿",null],["吻一下她的額頭，仍照原計畫去她那裡",null]]}],"visit":["夫君回來啦？聽說那位今天又哭著去找你告狀了？（咯咯笑）她的眼淚，值幾個錢？","夫君不用解釋，妾身哪會吃醋呢。（替你脫外衣，把上面一根別人的頭髮捻起來，吹走）只是記下了。"],"neu":["新人進門了？長得倒標緻。（摸了摸自己的臉）可惜，嫩的東西不經放。","她當了主母？呵呵，希望她坐得穩——那個位子底下，墊著不少人的骨頭。"],"crown":"夫君把凰戒交給妾身了？（套上手指，在燭火下慢慢轉）從今往後，誰笑、誰哭、誰死，妾身說了算。","otherMain":"恭喜姐姐當了主母～（福身時笑得最甜，起身就讓人去查她娘家的底細）","calm":["為了一點脂粉月例就紅了眼？出息。要鬥，就鬥個大的，鬥到對方再也起不來。","姐妹們，鬧大了傳到夫君耳裡，誰都討不了好。要撕，關起門來撕。"],"preg":"夫君，妾身有喜了。（拉著你的手按在小腹上，眼神卻冷靜得可怕）這孩子是你的護身符，也是我的。誰敢動他，我讓她全家陪葬。","birth":"粉雕玉琢的小傢伙。（抱著孩子，對著產房外那些來道賀的夫人笑）這孩子以後是要坐大位子的，各位，看清楚了。","kidWen":"多讀書，學會看人心。別像你外公王允，以為一個女人就能殺盡天下的惡人——要殺，得自己手裡有刀。","kidWu":"練武是好，可別學呂布，有勇無謀，為了一個女人殺了兩個爹，最後被人絞死在白門樓。","jealous":"她會笑得比平時更甜，轉頭就讓那個得寵的人吃不下飯、睡不著覺，三個月內自己來求你放她出宮。"},"lvzhi":{"ev":[{"t":"暗刪月例","d":"你發現 {m} 殿閣這個月的糧油、絲帛與銀炭被硬生生砍去大半。呂雉神色森冷地放下朱筆，連眼皮都沒抬：「她近來仗著幾夜恩寵便忘了晨昏定省，連見到本宮都敢怠慢。減她份例只是小懲，若再不知進退，下次砍的就不是炭火了。」","c":[["私下補回份例安撫 {m}，再柔聲哄呂雉莫把手段做得太絕",null],["當眾支持呂雉立威整頓內廷，誇她這把刀用得俐落",null]]},{"t":"當眾立規","d":"晨起定省時，{m} 僅遲了半刻，呂雉便當著滿殿夫人的面喝令她跪在冰冷的石階上足足一個時辰，自己端坐高臺慢慢飲茶，冷笑道：「莫以為昨夜被夫君抱過兩回，就能在本宮面前擺譜。當年戚姬舞得再好，照樣得去永巷髡髮舂米。」","c":[["出面把凍得發抖的 {m} 扶起來打圓場，私下再陪呂雉用膳賠罪",null],["冷眼默許她的威嚴，牽起呂雉的手回椒房殿共進早膳",null]]},{"t":"椒房獨斷","d":"呂雉把一卷重新擬定的內廷名冊拍在你案上，將幾名最受寵夫人的貼身宮婢全數發配苦役，換上清一色聽命於長樂宮的耳目，目光直直盯著你：「誰夜裡說了什麼話、喝了什麼藥，本宮都得清清楚楚。內廷安穩大於一切，夫君不會反對吧？」","c":[["握住她微涼的手背，稱讚她處事周密並允准大半調動",null],["明確駁回她越權換人，另賞一匣上等南海明珠安撫",null]]}],"visit":["在別殿溫存夠了？瞧你衣領上還沾著那股廉價脂粉味——別怪本宮沒提醒，溫柔鄉裡最容易養出不知死活的毒蛇。","那位妹妹倒是會裝柔弱掉眼淚，哼，本宮倒要看看她那張臉能讓你稀罕幾旬。"],"neu":["新人進門了？先叫她到椒房殿跪著把宮規背熟，免得日後不懂尊卑，害本宮動刀。","立別人當主母？夫君今日這步棋走得真大膽——且看她坐不坐得住這張沾滿血的位子！"],"crown":"后璽與凰戒既歸椒房殿，這座後宮便有了真正的鐵律。夫君只管去平定四方，內廷誰敢生事、誰敢懷鬼胎，本宮替你一個一個收拾乾淨。","otherMain":"既已冊立，本宮便靜坐冷觀——她若壓不住這滿宮妖孽，遲早還得求到長樂宮門前來。","calm":["都給本宮閉嘴！為了一匹絲帛、幾夜寵愛就敢在殿前撒潑？帶頭鬧事的拖去永巷杖責三十、扣發三月月例，誰再敢多嘴一句，直接拔舌！","統統跪下！你們私底下那點髒手段，本宮查得一清二楚。今日只罰禁足是給夫君留面子，再有下次，休怪凰戒無情！"],"preg":"夫君，本宮胞宮結珠，有喜了。（拉過你的手重重按在微隆的小腹上，眼底閃著狼一般的冷光）這孩子流著你我二人的血，生來就該坐大位。滿宮上下誰敢對他動半分心思，本宮定將她剁成人彘、夷她全族！","birth":"（產後臉色雖白，眸光卻亮得逼人，將嬰兒抱在懷中冷眼掃過滿殿）好孩子，哭聲洪亮，有帝王之氣。夫君，這才是你我江山真正的承繼者。","kidWen":"帝王心術與法家酷術全在書簡裡，給本宮字字讀透！絕不許長成劉盈那副見點血就哭的軟骨頭！","kidWu":"南北軍的兵權與手中利刃一刻也不可鬆懈！慈悲救不了命，唯有強橫才能讓人跪著聽你說話！"}},"pet":{"diaochan":[{"t":"套話","d":"貂蟬說荒原商隊裡混著敵對勢力的眼線，她要擺一場小宴，親自陪那人喝酒，喝到他把布防全說出來。","c":[["撥糧酒讓她去，事後不問她怎麼套的",null],["不准她去陪別的男人喝酒，送禮物哄住她",null]]},{"t":"花亭","d":"貂蟬嫌城裡光禿禿的殺風景，偎在你懷裡撒嬌，要木石在她殿旁蓋座賞月花亭——亭子要比主母的院子高。","c":[["答應修亭，順便讓全體夫人都能去賞花",null],["說戰事未歇，等奪下大城再蓋",null]]}],"lvzhi":[{"t":"整頓人事","d":"呂雉冷著臉遞上一卷名單，上面用朱筆圈出七名拖沓貪墨的倉吏與伍長，語氣不容置疑：「這幾個蛀蟲光靠訓誡沒用，授權本宮今晚抄家問斬，把首級掛在倉門外，明日工期必能快上三成。」","c":[["批准呂雉雷霆汰換、殺雞儆猴",null],["壓下殺令，改為罰俸訓誡以安人心",null]]},{"t":"預備暗樁","d":"呂雉察覺周邊軍閥頻頻派細作探查燈塔虛實，主動請撥一筆能量：「給我錢糧，本宮收買荒原商旅與流民眼線，不但摸清他們糧道，還能把他們的內眷買通。」","c":[["批准撥款，讓高后織起天下暗網",null],["婉拒暗中收買，把資源留在正面軍備",null]]}]},"cq":{"diaochan":{"tun":"連脂粉都得用糧食換，先讓倉房滿起來，妾身才睡得著。","qing":"主公對百姓越好，投奔的人越多。人多了，能用的棋子就多。","qiang":"前線將軍夠兇，妾身在城裡才睡得安穩。將軍們誰最兇，妾身記著呢。","kuang":"多採些上好木石，修城牆，也給妾身蓋座漂亮殿閣。","ji":"辦場祭天大典吧。神明靈不靈不知道，百姓看了會乖。","shou":"城牆修得結結實實，怪物進不來，想跑的人也出不去。"},"lvzhi":{"tun":"民以食為天，兵以糧為命。手握糧倉便掐住了全城咽喉，本旬必行屯田令。","qing":"對百姓輕徭薄賦、休養生息，他們才肯老實耕織納稅；狠手該留給朝堂與敵人。","qiang":"亂世只認刀把子。沒有強軍壓境，說再多仁義禮法都是廢話。","kuang":"木石是築城立威的筋骨，派民夫加緊開山採料，敢偷懶者鞭責。","ji":"星盤乃天命所歸。辦場盛大祭典，讓滿城上下都看清楚誰才是正統。","shou":"高牆深池才能立於不敗。本宮贊成堅壁令，先把根基釘死。"}},"wander":{"diaochan":"這荒原冷得教人發抖……幸好遇上了主公的星光。（理了理凌亂的衣襟，眼睛先看你的衣甲和刀）貂蟬，願隨主公——只要主公護得住我。","lvzhi":"（立在黑霧翻湧的荒原上，玄色裙襬被風刮得獵獵作響，眼底卻無半分懼色）星盤之光？哼，總比困在長樂宮裡看一群蠢貨強。漢高后呂雉在此——你若壓得住天下，本宮便替你執刀。"},"cap":{"diaochan":[null,null,null,"不再做亂世棋盤上的美人棋——今夜這場連環大戲，由妾身親手執子，誰該死，我說了算！"],"lvzhi":[null,null,null,"順我者昌，逆我者亡！這座城池的律法、血脈與江山，今日起全歸本宮與夫君共掌！"]},"hev24":{"diaochan":{"ev":[{"t":"連環離間","k":null,"d":"眼見{c}近日獨佔你的寵愛，貂蟬一邊跟她姐妹相稱，一邊讓人把{c}私下抱怨你冷落她的話，一字不漏地遞到你案頭。","c":[["看穿她的連環小計，私下警告她收手",null],["睜一隻眼閉一隻眼，今晚順勢去她那裡",null],["當眾替{c}解圍，斥責兩人都不許再鬧",null]],"after":"哎呀，夫君怎麼把帳算到妾身頭上？那些話又不是我替她說的——我只是讓夫君聽見而已。"},{"t":"毒粉栽贓","k":null,"d":"{b}用了新領的香粉，臉上起了一片紅疹，宮人在貂蟬侍女的房裡搜出同樣的粉包。貂蟬哭著說是有人陷害，眼淚掉得恰到好處。","c":[["順藤摸瓜查明真相，護住貂蟬",null],["覺得另有蹊蹺，命人封存證物另查",null]],"after":"後宮本來就是沒硝煙的戰場。（擦乾眼淚，低聲笑）粉包是我放的，又怎樣？她那張臉，本來就不配擺在夫君面前。"},{"t":"病妝騙寵","k":null,"d":"聽說你今晚要去{b}殿裡，貂蟬用梅汁染紅手帕裝咳血，披頭散髮半躺在軟榻上，衣襟敞著，派人去請你。","c":[["又氣又笑，把她按回軟榻上「好好治治妳這病」",null],["擦掉帕上的梅汁，嚴肅訓斥她不許再裝",null]],"after":"咯咯，兵不厭詐嘛～不用點手段，夫君今晚就睡在別的女人身上了。"}],"cold3":"連著三回都睡在她那兒……（把一根珠釵掰成兩截）好，妾身記住了。她能讓夫君留三晚，我就能讓她三個月見不到夫君。","crownR":"多謝各位妹妹道賀呀～（舉杯環顧，一個一個看過去）今天誰沒來、誰笑得勉強，妾身都看在眼裡了。"},"lvzhi":{"ev":[{"t":"巫蠱死局","k":null,"d":"{b}近來夜夜承恩，一日內廷侍衛竟從{b}寢殿井底撈出一隻插滿銅針的桐木人偶，底下壓著寫有詛咒星盤熄滅的血帛，人證物證一應俱全。呂雉端坐主位慢條斯理地啜茶，嘴角掛著一絲冷得發寒的笑——你一眼便看出那字跡是刻意臨摹{b}筆法的栽贓局。","c":[["當眾拆穿血帛破綻救下{b}，私下冷聲警告呂雉收手",null],["明知是呂雉設的死局卻順水推舟配合立威，藉機冷落{b}",null],["命人當場焚毀木偶並各罰月例，強行壓下這場巫蠱案",null]],"after":"夫君心太軟了。在未央宮裡，對威脅留半分餘地，明日躺進棺材的便是自己。……罷了，既然夫君嫌這次破綻太多，下回本宮做得乾淨些便是。"},{"t":"密報反骨","k":null,"d":"深夜暴雨，呂雉獨入書房，將一封沾著蠟封的密信拍在你案上，目光陰森如鷹：「夫君，{b}昨日私下與{c}飲酒，竟敢抱怨你冷酷獨斷，還商量著聯手拉攏前朝清流架空內廷。這兩個賤人已生反骨，本宮請旨將她們打入永巷禁足、削去位分！」","c":[["採信呂雉密報，嚴懲{b}與{c}以固椒房威信",null],["當面扯碎密信，冷聲告誡她莫在後宮大興冤獄",null]],"after":"忠言逆耳。本宮替你盯著滿宮人心，從不指望她們感恩，只望夫君記清楚——這城裡誰都可以反你，唯有本宮與你性命相連。"},{"t":"棄卒保車","k":null,"d":"呂雉先前與{b}聯手削減各殿用度，惹得六宮怨聲載道；今日眾人跪在殿前哭訴時，呂雉竟面不改色地把{b}推出去頂罪，冷聲道：「一切苛扣皆是{b}急於邀功、背著本宮擅自下令。本宮失察，願自罰一旬月例。」當場把{b}氣得臉色鐵青、昏死在石階上。","c":[["看穿她棄卒保車的狠辣，卻欣賞她這手借刀平怨，順勢順水推舟",null],["拒絕讓{b}獨自背鍋，責令呂雉當眾致歉並補發份例安撫",null]],"after":"成大事者本就不拘小節。{b}連這點風浪都扛不住，活該當那顆棄子。夫君，帝王之術哪裡有半分溫情？"}],"cold3":"連著三夜宿在同一個賤人榻上……（指尖將青玉茶盞捏出裂紋）夫君，你是忘了當年戚夫人被剃光頭髮、斬斷四肢丟進茅廁的模樣，還是覺得本宮這把刀太久沒見血了？","crownR":"都抬起頭來，看清楚本宮指間這枚凰戒。從今日起，椒房殿的規矩便是六宮死律——順本宮者榮華不斷，逆本宮者，永巷與掖庭獄隨時替她留著位子。"}},"hact":{"diaochan":{"討好":["夫君，妾身新編了一支只給你看的舞，穿的衣裳……很少。","這塊玉佩是我託商隊找了好久的。（親手繫在你腰上，順勢解開了你另一條帶子）"],"爭權":["主母連這點採買帳都理不順，不如讓妾身來？我保證，三個月內她的人一個不剩。","後宮人事向來能者居之。姐妹們要是不服，可以來找我談——談完了，就服了。"],"結黨":["妹妹長得這麼美卻總受委屈，真教人心疼。跟著姐姐，姐姐替妳出頭——出完頭，妳欠我一次。","單打獨鬥多累，咱們結成一盟。先把主母拉下來，剩下的，我們再分。"],"進讒":["夫君，妾身本來不想說的……可她昨晚對著你的畫像啐了一口，好幾個人都看見了。","{b}姐姐看起來端莊，怎麼私底下跟侍衛走得那麼近？妾身親眼見她深夜從侍衛房裡出來，衣帶都沒繫好。"],"收買":["這幾盒上等脂粉和銀錁子賞你。往後她殿裡吃什麼、說什麼、夜裡誰進去，一五一十來告訴我。","廚房管事辛苦啦，這點心意拿去。她那份湯，以後多放點鹽——放到她喝不下去為止。"],"干政":["夫君，那位猛將性子太烈，早晚惹禍。不如明升暗降，調去守城門——讓他自己憋死。","聽說那位將軍最近心情不好？妾身去陪他喝兩杯，套套他的話。（笑）夫君放心，只喝酒。"],"祈福":["願星盤清光常照，護佑夫君平安。（跪在香案前，心裡念的卻是另一個人的名字和『早死』二字）","點一盞長明燈，求來年沒有黑霧、沒有戰亂——也沒有新人進宮。"],"調停":["好啦好啦，為一匹絲綢吵紅了臉，給夫君看笑話嗎？絲綢我拿走了，你們誰都別要。","鬧到夫君耳裡誰都討不了好。聽姐姐的，各退一步——退的那步，你們誰欠我人情，我記著。"]},"lvzhi":{"討好":["夫君，這卷新修的稅律與考課章程本宮核了三遍。外頭天寒，溫了關中濁酒與炙羊肉，喝完今夜就留在椒房殿罷。","你肩上的江山重得很，別總對著那群庸才費神。過來坐下，讓本宮替你鬆鬆衣領——今夜這長樂暖帳，只伺候你一人。"],"爭權":["主母若連內廷採買與宮婢賞罰都壓不住，不如早早交出凰戒，免得把後宮鬧成菜市口！","從今日起，少府撥進後宮的每一匹錦緞、每一石米糧，全得先過椒房殿的印信！"],"結黨":["識時務者方能活命。站到本宮身後，前朝的官缺、後宮的份例，自然少不了妳那一份。","弱者只會抱團哭泣，強者聯手才能瓜分天下。妳既肯投效椒房殿，本宮便保妳步步高升——只要妳別長反骨。"],"進讒":["夫君，{b}近來頻頻派貼身宮婢去軍營送酒送衣，與幾名領兵校尉眉來眼去，這等私通外將的苗頭，不可不防！","{b}在你面前裝得溫順賢良，背地裡卻暗中記下你每旬行蹤、收買書房小吏，這等蛇蠍心腸，留著必成大患。"],"收買":["這批金餅賞給少府管事與各門宿衛。記清楚，這座城裡誰給你們發餉，誰就能一句話保你們全家富貴！","挑幾個口風緊、手腳俐落的宮婢安插進各殿去，她們家人的田產與安頓，全由本宮私庫出。"],"干政":["韓信這類功高震主的武夫，絕不能讓他久握精銳！這份明升暗降的調令本宮已擬好，夫君用印便是。","府衙那三名陽奉陰違的官吏，本宮昨夜已讓人革職下獄，明日便換上外戚派舉薦的能吏。"],"祈福":["星盤在上，願我夫妻共掌歸墟、大漢氣運重振，凡敢阻路者皆死無葬身之地！","焚香告天，不求虛無慈悲，只求鐵血威權永固於椒房殿！"],"調停":["都給本宮住嘴！為了這點雞毛蒜皮的事吵得烏煙瘴氣，全拖去永巷跪兩個時辰、罰俸一旬！","這件事本宮已經拍板定案，誰若不服，大可去書房向夫君哭訴——看他信妳的眼淚，還是信本宮的手段！"]}},"hpow":{"diaochan":["夫君，現任主母整天板著臉，把後宮弄得死氣沉沉。把凰戒換給妾身吧，我保證，三個月內後宮人人笑臉迎你——笑不出來的，就不在了。","後宮這麼多姐妹沒人管，遲早亂套。夫君，把凰戒交給最懂人心的妾身——我懂她們每個人最怕什麼。"],"lvzhi":["夫君，現任主母軟弱無能、御下不嚴，後宮早已暗潮洶湧。把凰戒交給本宮，當年我能替大漢鎮住諸侯與百官，今日便能替你把這座後宮管得鐵板一塊！","國不可一日無君，內廷不可一日無鐵腕之主。夫君，這枚后璽與凰戒，除了本宮呂雉，滿宮上下還有誰壓得住陣腳？"]},"hbig":{"diaochan":[{"t":"毒酒連環","k":null,"d":"{b}喝下晚宴上的桂花釀，當場口吐白沫昏死過去。貂蟬第一個撲上去哭喊，第一個指著那壺酒說是誰溫的——溫酒的宮女，是另一位夫人的人。","c":[["信貂蟬所言，徹查{c}殿閣並把人關起來",null],["認定貂蟬脫不了干係，下令關押",null],["怒極之下兩人一併禁見，整頓宴飲",null]],"after":"（擦掉眼角的淚，靠進你懷裡，聲音軟得像水）夫君信我，就夠了。（貼著你的胸口，你看不見她在笑）"},{"t":"暗夜通敵","k":null,"d":"斥候在城外攔下一名信使，搜出貂蟬親筆寫給敵對勢力首領的情信，字句曖昧，還附著一張城防圖。她說這是反間計，是故意讓敵人信她。","c":[["相信她的反間之計，私下放人",null],["真假都不容私通敵營，下令關押",null],["念及舊情不忍殺她，流放荒原",null],["通敵大罪無可饒恕，忍痛下令處死",null]],"after":"夫君連這種罪都肯信我……（伏在你膝上，聲音發顫）你知道嗎，我真的跟他睡過。為了那張圖是真的，我得讓他信我。"},{"t":"火燒偏殿","k":null,"d":"深夜{b}的暖閣突然起火，燒死了兩個宮女，{b}被抬出來時半張臉都焦了。火場裡找到一盞貂蟬殿裡才有的琉璃燈。","c":[["認定貂蟬縱火，罪證確鑿，下令關押",null],["覺得燈盞留得太刻意，只禁見貂蟬",null],["壓下此事，說是燭火失慎，私下了結",null]],"after":"夫君若信我是清白的，我就是清白的。（低頭撫平裙襬）至於她的臉——那是她的命。"}],"lvzhi":[{"t":"未央奪印","k":null,"d":"呂雉權勢如日中天，竟趁早朝剛散、你尚未起身之際，親率已歸附她的{b}與數十名身穿玄甲的長樂宮衛兵踏入正殿，將一卷「廢黜主母{c}、改由呂雉執掌后璽統轄六宮」的擬詔重重拍在你案上，目光冷冽而居高臨下：「夫君，{c}德不配位、管不住內廷，滿宮管事皆願奉本宮為主。今日這枚凰戒，請夫君重賜！」","c":[["欣賞她這股逼宮奪權的霸氣，順勢默許她擴權並私下安撫{c}",null],["拍案大怒，斥責她竟敢挾兵逼宮，下令將呂雉關入掖庭獄四旬",null],["奪過擬詔當眾撕成碎紙，罰她與{b}禁見三旬以立君威",null]],"after":"（直直盯著你的眼睛，唇角勾起一抹既危險又帶幾分讚賞的冷笑）夫君果然沒軟到任人拿捏。……無妨，這局本宮認栽，但后璽早晚會回到我手裡。"},{"t":"人彘之怒","k":null,"d":"{b}仗著正得聖寵或身懷六甲，竟敢在眾人面前頂撞呂雉，暗諷她年長色衰、遲早失勢。呂雉當時只冷冷一笑，隔日便以「核查胎安、教習宮儀」為由把{b}扣進椒房殿暗室，剃去她半邊長髮、以燒紅的鐵鉗逼問酷打。等你帶兵破門時，{b}衣衫撕裂、滿身焦痕血污、幾乎斷氣，呂雉卻平靜地拿絲帕擦拭指尖血跡：「沒斷她手腳、沒挖她眼珠，已經是看在夫君面子上了。」","c":[["勃然大怒，絕不容許私設酷刑，當場下令關押呂雉五旬並搶救{b}",null],["駭於她骨子裡的殘酷毒辣，忍痛下令將呂雉流放荒原以安六宮",null],["念及呂雉治城功高，僅罰禁見三旬並重禮安撫受創的{b}",null]],"after":"夫君覺得我太狠？當年我在未央宮裡對付戚夫人，可比這痛快十倍。……你若管不住她們的嘴，本宮便親手替你縫上。"},{"t":"鳩毒清側","k":null,"d":"呂雉認定{b}夜夜在你枕邊吹風、暗中替政敵說項，已成心腹大患，竟買通藥房在{b}每日服用的安神湯裡摻入慢性鴆毒。{b}連喝三旬後驟然嘔血倒地、腹痛如絞，華佗驗出毒源直指椒房殿私庫！面對鐵證，呂雉連眉頭都沒皺一下，冷冷道：「當年趙王如意喝的也是這味藥。除掉一個禍水，本宮問心無愧。」","c":[["痛心震怒，下令將下毒的呂雉關押五旬並削去全部職權",null],["後宮下毒罪無可赦，忍痛下令賜死呂雉以儆效尤",null],["念及共患難舊情不忍殺她，下令流放荒原並全力救治{b}",null]],"after":"哈哈哈哈，終究還是為了別的女人對本宮動手了……好，這份無情，本宮一筆一筆記在骨頭上！"}]},"hstat":{"diaochan":{"jail":"夫君終於肯來看妾身了？這牢房又濕又冷，再關下去，這張臉就要爛了。（隔著柵欄抓住你的手，往自己衣襟裡塞）摸摸看，冷不冷。","ban":"不讓見面？呵呵，那妾身就在窗邊吹一夜冷風，吹到病倒，看是誰心疼。","spoil":"誰的舞最美、誰最懂夫君的心，大家心知肚明。多花點錢打扮，是為了夫君的臉面——也為了讓她們眼紅。","inj":"好疼……（把傷口亮給你看，故意讓血流到手腕上）這道傷要是留了疤，夫君會不會就不要我了？會的話，傷我的人，我要她十倍還。","exileGo":"當年董卓和呂布為了我殺得你死我活，都捨不得傷我一根頭髮，夫君卻狠得下心。好，妾身走。你記著，我會回來的。","exileBack":"夫君，連黑霧都捨不得吞掉妾身呢～（貼上來，身上還帶著荒原的血腥味）這一次，誰再想把我趕走，我先送她走。","exec":"舞完最後一曲，終究還是這種下場……（解下髮簪，長髮披下來，笑得淒豔）夫君，你會記得我的臉嗎？你會的。你會夢見它，夢一輩子。","cleared":"我就知道夫君是向著我的～害我受了這麼大委屈，今晚你得好好補償。（附耳）還有，誣陷我的那個人，交給我處置。","otherExec":"（掩唇輕嘆，眼底一點寒光）紅顏薄命啊……（轉頭對侍女低聲）她的首飾，挑幾件好的送到我這兒來。","ally":"姐姐妹妹聯手，這後宮還有什麼辦不成的？（握住對方的手，笑得真誠）只要妳別比我先得寵。","betrayed":"呵，跟我玩過河拆橋？妳忘了，連環計是誰的看家本事。妳的下場，我已經替妳排好了。","win":"哎呀，怎麼這麼不經鬥？少了一個礙眼的，空氣都清新了～夫君，今晚來我這裡慶祝。"},"lvzhi":{"jail":"夫君，你今日敢把本宮鎖進掖庭獄，明日就得防著前朝後宮亂成一鍋粥！放我出去，咱們重新算這筆帳。","ban":"奪我職司、禁我出門？哼，本宮便坐在椒房殿裡喝茶等著看，沒了我這把刀，誰替你壓得住那群狼子野心之徒。","spoil":"這座燈塔一半的糧稅與規矩是本宮拼出來的，多佔些權勢與珍玩，天經地義，誰敢嚼舌根？","inj":"這點皮肉傷算什麼？當年楚營裡的苦都熬過來了。這筆血債本宮記在心裡，傷好之日，便是仇人斷氣之時。","exileGo":"好一個過河拆橋！天運者，你今日不殺我卻放虎歸山，來日再見，本宮定教你後悔手軟！","exileBack":"（玄衣染滿荒原血塵，冷笑踏進殿門）黑霧都吞不下本宮的命。那些以為我呂雉死在外頭的蠢貨，統統洗乾淨脖子等著！","exec":"哈哈哈哈！成王敗寇，本宮認了！天運者，能逼得你親手下殺令，也不枉本宮與你鬥這一場！","cleared":"夫君總算擦亮了眼。至於那幾個敢構陷椒房殿的賤婢，現在該交給本宮帶回永巷處置了吧？","otherExec":"（端起茶盞輕抿一口，眼底寒光一閃）早知今日，何必當初。惹怒君王與本宮，這便是下場。","ally":"聰明人就該看清風向。只要妳老實聽本宮號令，這後宮的榮華與靠山，本宮全給妳。","betrayed":"敢背叛椒房殿？好得很，我定要讓妳活著求死、後悔生在這世上！","win":"區區草芥，也敢擋本宮的路？既然倒了，就該斬草除根，永絕後患。"}},"fac26":{"mem":{"diaochan":[null,"她一生周旋在權臣和武夫之間，用一張臉讓董卓和呂布互相殘殺。外戚派是她最順手的戲台——男人的野心，她最會利用。"],"lvzhi":[null,"大漢臨朝稱制十六載的鐵腕高后，誅韓信、醢彭越、封諸呂掌南北軍，天生便是外戚派最令人膽寒的領袖。"]}},"blood":{"conf":{"diaochan":["（眼眶瞬間紅透，死死抓住你的衣袖，指甲掐進你的肉裡）夫君怎麼忍心聽這種毒話？這孩子天天喊爹爹，你要冤枉我們母子嗎？說這話的人，我要她的舌頭！","（卸下所有嬌媚，唇邊浮起一絲冷笑）……終究瞞不過你。是，不是你的。是那個夜裡從窗口翻進來的校尉。孩子什麼都不懂——要殺，殺我；你若動他，我做鬼也纏著你。"],"lvzhi":["笑話！敢把這等穢水潑到椒房殿與本宮骨血頭上，真是活膩了！夫君把造謠的賤奴交出來，本宮先拔她的舌頭，再讓你看看什麼叫清白！","（臉色冷靜得令人背脊發寒，絲毫不避你的目光）……既已被你查出，本宮無須狡辯。當年楚營二十八個月，陪在我身邊的是審食其；這座深宮裡你冷落我時，本宮自然也有自己的消遣。孩子不是你的，你要殺要剮，本宮接招便是。"]}},"agenda":{"diaochan":{"歸來被俘":["繩子把手腕都勒破了……（把流血的手腕伸到你面前，眼神卻勾著你）夫君，看在那些夜裡的份上，輕點罰。或者——親自來罰。"]},"lvzhi":{"歸來被俘":["（雙手雖被麻繩反縛，腰背卻挺得筆直，冷眸直刺向你）敗軍之將何言勇。天運者，你今日若留我性命，他日莫怪本宮反咬一口。"]}},"ownx":{"diaochan":[{"k":null,"t":"假死試心","d":"你近來冷落貂蟬。一天侍女哭著來報，說貂蟬留書投井了。你趕到時井邊只有一隻繡鞋——三天後，有人在城外客棧看見她，正跟一個年輕商人喝酒。","c":[["親自去客棧把這個戲精揪回來",null],["斥她拿生死戲弄君心，押回後宮禁足",null],["震怒之下關押三旬，絕不姑息",null],["將計就計，大張旗鼓替她辦喪事，看她回不回來",null]],"after":"誰讓夫君近來總不理我？（若無其事地剝著葡萄）那個商人？不過是借他的房間睡了三天，看你急不急。"},{"k":null,"t":"暗度敵情","d":"前線一場奇襲落進敵軍埋伏，死了三百人。查下去，洩漏軍情的是貂蟬——她說是枕邊無意間說出去的，那個枕邊人，是敵方派來的俊俏樂師。","c":[["通敵賣主，忍痛下令關押",null],["念及舊情不殺，流放荒原",null],["心軟聽信她「故意設局反間」的說法",null],["雷霆震怒，依軍法當場處死",null]],"after":"夫君居然肯饒我一命……（笑得眼淚都出來了）三百條命，換我一條。看來在你心裡，我比三百個兵值錢。"},{"k":null,"t":"枕邊要挾","d":"深夜暖閣，貂蟬靠在你懷裡，手指在你胸口畫圈，忽然說：你上回私下處置的那個大臣，證據在我手上。給我一座城的封邑，這件事就爛在我肚子裡。","c":[["扣住她的手腕翻身壓住她，反客為主",null],["欣賞這隻狐狸的膽子，順勢答應",null],["勃然大怒，下令關押膽敢要挾君主的人",null]],"after":"哎呀，若不給夫君出點難題，你哪會記得我有多危險？（舔了舔被你咬破的嘴唇）"},{"k":null,"t":"虛報賑災","d":"貂蟬上月請撥四十石糧，說是賑濟城外流民。查下去，糧食全換成了西域的胭脂和金步搖，流民那邊餓死了七個。","c":[["當場拆穿追回物資，罰她禁見",null],["無奈笑她愛美成癡，只追回一半",null],["嚴懲貪墨賑災糧，關押待審",null]],"after":"人家打扮得漂漂亮亮，最後還不是給夫君看？七個流民……（撥弄著新步搖）他們本來也活不長。"}],"lvzhi":[{"k":null,"t":"當眾駁旨","d":"早朝議政時，你方才下達一道赦免降將、授其兵權的詔書。呂雉竟當著滿朝文武的面起身走下高階，面無表情地從謁者手裡奪過竹簡、咔嚓一聲折成兩段，居高臨下地盯著你：「夫君今日糊塗了！這幾個反覆無常的武夫豈能握兵？這道旨意本宮駁回了，南北軍與諸營一律按長樂宮新令行事！」滿殿臣子嚇得伏地不敢出聲。","c":[["壓下怒火順水推舟，誇高后慮事周全、替彼此留足體面",null],["拍案震怒，當眾斥責她越權犯上並罰禁見三旬",null],["雷霆喝令宿衛當殿拿下呂雉關入掖庭獄四旬，徹底立住君威",null],["冷笑著當場重書詔令命她親口宣讀，散朝後再與她徹底攤牌",null]],"after":"夫君若不想被我當眾折簡，往後下旨前便該先來椒房殿商議。……不過，你發狠壓住本宮的樣子，倒真有幾分高祖當年的狠勁。"},{"k":null,"t":"稱制專權","d":"呂雉權勢燻天，竟不經你允准，逕以「高后」名義單獨召見各大分城守將與郡守，更命少府工匠將長樂宮門闕改建為與你正殿同等規格的玄金龍鳳雙闕。面對你的質問，她慢條斯理地撥弄著茶末：「這座江山一半是本宮替你穩住的，見幾個外臣、修幾道飛簷，夫君難道連這點氣量都沒有？」","c":[["默許她的帝后共治規格，甚至親題長樂宮匾額以示尊寵",null],["下令即刻拆除逾制雕飾並罰禁見三旬，嚴禁私見外臣",null],["下令將野心膨脹的呂雉關押三旬、收繳實權",null]],"after":"當年大漢未央宮裡，百官見我都得稱制叩首。……罷了，既是你的城池，本宮便暫且收斂三分鋒芒。"},{"k":null,"t":"暗掌兵符","d":"暗衛深夜呈上驚天密報：呂雉暗中拉攏了兩名掌管南北城門的校尉，私鑄了半枚調兵銅虎符，打算在你親征出城或遇險之際，第一時間接管主城防務、徹底架空你的直轄軍權！面對鐵證，她非但毫無懼色，反而冷笑反問：「當年呂台、呂產掌南北軍，大漢才安穩八年。我這是在替你留後手，免得你哪天戰死了，城池落到外人手裡！」","c":[["私鑄虎符等同謀逆，雷霆下令關押呂雉五旬並徹查親信",null],["念及往日共患難情分不忍下殺手，下令流放荒原十二旬",null],["篡權謀逆罪無可恕，鐵血下令當場賜死呂雉以絕後患",null],["明知她野心滔天卻仍離不開她的手腕，僅沒收假虎符並暗中防備",null]],"after":"哈哈哈哈！好一個天運者，連本宮埋了這麼深的暗棋都能連根拔起……只要你今天沒殺我，咱們這場權力棋局便永無止境！"},{"k":null,"t":"扣糧要挾","d":"你不肯撤換一名曾當庭彈劾她專權的清流御史，呂雉竟直接動用椒房殿安插在少府與糧倉的心腹，死死卡住明日大軍出征的運糧調撥符，冷著臉走進書房：「夫君，要嘛把那個嘴碎的酸儒貶去荒原，要嘛明日三軍自己餓著肚子迎戰黑霧——你選一個。」","c":[["迫於戰機緊迫暫時妥協，調離那名御史以換取放行軍糧",null],["親率宿衛直衝糧倉強行破封運糧，同時將呂雉關押四旬嚴懲",null],["怒斥她拿三軍性命當籌碼，奪其職司並罰禁見三旬",null]],"after":"權力握在手裡，本來就是拿來逼人低頭的。夫君今日既敢硬破我的封條，本宮倒也服了你這股狠勁。"}]},"hwin":{"diaochan":{"爭權":"那個要緊的缺額空著多可惜。妾身已經替夫君安插了最懂事的人——懂事，就是只聽我的話。","進讒":"瞧她平日那副高傲樣子，如今還不是關進冷院數日子？夫君果然最疼我。（輕笑）她到死都不會知道是誰說的。","干政":"那個不知進退的武夫總算調走了。少了他在朝會上瞪眼，夫君耳根清淨，妾身的人也好辦事。","收買":"這支步搖原本就襯我的衣裙，從庫裡先拿了，順手賞了管事幾吊錢。帳上妥當得很，誰查都查不出來。"},"lvzhi":{"爭權":"那個要緊的位子本宮已替夫君安頓妥當，換上的全是椒房殿信得過的人，夫君不必費心。","進讒":"早該把那等不知尊卑的賤婢關進永巷了。夫君今日處置得乾淨俐落，甚合本宮心意。","干政":"功高震主又不服管束的武夫，留著早晚是禍害。削他兵權，本宮這是在替你固本。","收買":"少府物資原該由椒房殿統籌調撥。這批珍玩本宮取去賞賜心腹，誰敢多吐半個字？"}},"duty":{"diaochan":[{"n":null,"d":null,"eff":null,"line":"刀劍砍不開的鐵壁，有時一封密信、一夜枕席，它就從裡頭塌了。董卓的郿塢，就是這麼塌的。"},{"n":null,"d":null,"eff":null,"line":"人心最好擺布。交給妾身，滿城上下誰怕什麼、誰要什麼，三天之內我全摸清。"},{"n":null,"d":null,"eff":null,"line":"帳目算得巧，宴席體面，還能替夫君省下三成糧銀——省下來的，妾身抽一點胭脂錢。"}],"lvzhi":[{"n":null,"d":null,"eff":null,"line":"椒房殿令出必行！誰敢怠慢農桑與築城工期，一律按大漢嚴律論處！"},{"n":null,"d":null,"eff":null,"line":"這座城裡的每一道牆縫都有本宮的耳目，有我在，宵小休想翻出半分浪花。"},{"n":null,"d":null,"eff":null,"line":"權力場上從不信眼淚。本宮替夫君把規矩立死，文武百官自然伏首稱臣。"}]},"meddle":{"diaochan":["夫君何必為那個傲氣將領傷神？妾身備了厚禮和軟話，今晚親自去他營裡，明天他就服貼了。","那位大人近來跟外派走得太近……不如調去閒職。他不肯走，妾身有法子讓他身敗名裂。","這場談判交給妾身。我陪他們喝一晚上酒，保管替夫君省下一半賠禮——他們會醉，我不會。"],"lvzhi":["夫君心太軟了！這名功高震主的猛將留著必成第二個韓信，本宮已擬好削權調令，你只需用印。","少府與各倉的帳冊本宮已全數接管核清，揪出三個手腳不乾淨的倉吏，已先打入掖庭獄候審。","前朝那些酸儒越說越放肆，今日不殺一兩個封口，明日他們就敢指著你的鼻子罵了！"]},"night2":{"diaochan":[[[null,"夫君今夜來得這麼遲，又被前朝那些老東西絆住了？"],[null,"確實棘手，幾派人馬吵得不可開交。"],[null,"（手指搭上你的肩頭揉捏，慢慢滑進衣領）別皺眉了。今夜先把朝堂忘掉，讓妾身替你解乏——用什麼解，你說了算。"],[null,"至於那些不聽話的大臣，明天妾身替你一個一個收拾。（吹熄了燈）"]],[[null,"世人說紅顏禍水，說我用連環計攪亂了天下。"],[null,"那是他們沒看見亂世裡女人的身不由己。在我這裡，妳不用當任何人的棋子。"],[null,"（眼波一顫，收起媚態，盯著你看了很久）……身不由己？夫君錯了。董卓死的那天，我笑了一整夜。我從來不是無辜的。你還要我嗎？"]],[[null,"這爐沉水香是妾身特調的，最能讓人睡沉。"],[null,"香氣清幽，確實讓人靜下心來。"],[null,"（掩唇輕笑，吹熄案上多餘的蠟燭，跨坐到你身上）睡沉了，就不會半夜起身去別的院子了。今夜，哪兒也不許去。"]]],"lvzhi":[[[null,"今日朝會上那幾個不知天高地厚的武夫，夫君壓得還算俐落。"],[null,"能得高后一句稱讚，看來我今天沒白費工夫。"],[null,"（唇角微揚，解開外袍半邊繫帶，露出一段雪白鎖骨，親手替你斟滿關中烈酒）壓得住群雄的男人，才配壓得住本宮。喝完這碗，今夜椒房殿的燭火可不會早滅。"]],[[null,"滿城上下都怕本宮心狠手辣，連親生兒子見了我也繞道走。夫君每夜抱著我這副沾滿血的身子，就從沒怕過？"],[null,"我知道妳的狠從不是盲目發瘋，那是妳在亂世裡活下來、替咱們守住這座城的本事。"],[null,"（眸色驟深，指尖順著你的頸側緩緩滑下，呼吸微熱）……這世上，唯有你敢直視本宮的血手還不退半步。過來，別說話了。"]],[[null,"夜深了，椒房殿四門皆已落鎖，外頭的殺伐明早再議。"],[null,"難得連妳也肯放下竹簡早些安歇？"],[null,"（緩步走近，衣袂滑落間透出成熟婦人獨有的濃烈暖香，手指勾住你的腰帶輕輕一扯）江山要緊，可今夜這副身子正熱著——夫君若敢走神，本宮可要動私刑了。"]]]},"talk2":{"diaochan":{"陌生":["主公這樣盯著妾身瞧，是覺得荒原總算添了點春色，還是在估價？","打仗妾身不行，看透男人——妾身沒輸過。"],"熟識":["主公今天眉頭緊鎖，又是哪個傲氣將軍惹您了？說給妾身聽，我替你治他。","在這座城待得越久，越覺得主公比董卓、呂布有意思——至少你還沒蠢到讓我看不起。"],"信賴":["我累了，不想天天戴著面具……只有在你面前，我能把臉上的笑卸下來。","謝謝你從沒把我當成一件拿來交換的寶物。這份情，我會用命還，也會用別人的命還。"],"親密":["夫君今夜來得正好，暖閣薰了你最愛的沉水香，被子也暖好了，別急著走。","我的連環計對天下男人都管用，偏偏遇上你就失靈——所以我只好把你綁在床上。"],"誓約":["此生不再為誰設局、不再為誰流離。貂蟬這顆心落在你手裡了，你敢摔，我就跟你同歸於盡。","夫君要一輩子把我寵在懷裡，絕不讓別人搶了我的位子——搶的人，會死得很難看。"]},"lvzhi":{"陌生":["這座城雖有雛形，規矩卻鬆散得像一盤散沙。天運者，你若下不了狠手，本宮可以代勞。","亂世裡，心軟的人連自己的骨頭都保不住。"],"熟識":["你近來處事越來越有帝王城府，比當年劉季在沛縣起兵時沉穩多了。","內廷與糧稅這些瑣事交給本宮，你只管專心對付外頭的黑霧與軍閥。"],"信賴":["滿城英靈各懷鬼胎，唯獨本宮與你是真正綁在一條船上、一榮俱榮。","只要你永遠比旁人更強、更狠，椒房殿便永遠是你最硬的靠山。"],"親密":["（指尖替你整平衣領，順勢貼近你胸膛）外頭防著百官已經夠累了，進了椒房殿，把甲卸下來吧。","能讓大漢高后親手溫酒、親手解衣的男人，這世上唯有你一人——你最好別讓我失望。"],"誓約":["這座江山是你打的，也是本宮替你一刀一血守下來的。此生此世，咱們夫妻共掌乾坤！","誰敢動你半分，本宮便讓她嚐嚐人彘與菹醢的滋味——這便是高后的誓言。"]}},"negtag":{"who":{"diaochan":{"tags":null,"why":"被當成禮物轉手了兩回，從王允到董卓到呂布，她只學會一件事：男人靠不住，能靠的只有自己手裡的牌和別人的軟肋。"},"lvzhi":{"tags":null,"why":"大漢臨朝稱制之高后，歷楚營二十八月屈辱與晚年冷落，骨子裡極度記仇且工於心計，凡敢觸逆鱗者必十倍血償。"}}},"office2":{"shanggong":{"assign":{"diaochan":"既蒙夫君託付尚宮印信，貂蟬自當以柔克剛——笑著把六宮管得服服貼貼，不服的，笑著送走。","lvzhi":"尚宮印信交予本宮？甚好。從今日起，六宮上下誰敢越矩生事、誰敢暗通款曲，本宮定教她們知道什麼叫椒房鐵律！"}}},"love":{"special":{"diaochan":[{"lv":null,"t":"沉香迷夢","d":"你本只想在暖閣坐一盞茶，貂蟬卻赤著腳踩過紅毯，反手把你的腰帶纏在自己指上，一圈一圈收緊。她眼眶發紅，聲音發顫：「今晚別去{b}那裡。我不設局了，我就是想你抱我——你走出這道門，我就把這條腰帶燒了。」","c":[["心一軟，把她抱起來，今夜所有安排全推掉",null],["吻掉她眼角的淚，答應明晚整夜都給她",null],["認定又是苦肉計，笑著把腰帶抽回來走人",null]],"after":"燭火滅的時候她還攥著那條腰帶。天亮宮婢進來收拾，只見滿地衣衫、半截燒殘的香，和她頸上一圈紅痕。她對著銅鏡看了很久，沒讓人塗粉。"},{"lv":null,"t":"暗網織局","d":"你查出來了：{b}這陣子舞衣被剪、茶會上當眾出醜、舉薦的官員接連被彈劾下獄，連她貼身宮婢都吊死在井邊——幕後全是貂蟬。她不躲不辯，掩著嘴笑，眼底燒著一團火：「誰叫她搶你的眼神？那宮婢是我叫人勒的，舌頭割了才丟下井。我不過替你挑一挑，誰配留在你身邊。」","c":[["被她這股狠勁鎮住，把事壓下，反手將她拉進懷裡",null],["嚴令她立刻收手，暗中補償{b}",null],["怒她拿連環計對付自家後宮，下令禁見三旬",null]],"after":"你若嫌我手髒，就只看我一個——只要你眼裡沒有別人，我就不必再殺人。"},{"lv":null,"t":"孤身入敵","d":"敵酋設下鴻門宴要你的命。貂蟬先一步看穿，帶著偽造的密契獨自入營，陪酒、獻舞、睡在敵將帳裡三夜，第三夜在他酒裡下了藥，把伏兵圖抄在自己大腿內側帶回來。她撲進你懷裡時渾身是傷：「布防全在這裡。那個人——我走之前割了他的喉。」","c":[["抱緊她，發誓再不讓她一個人去送命",null],["照她帶回的圖大破敵軍，首功與最高尊榮全給她",null],["親手替她洗淨一身血污，許諾平定歸墟後只守她一人",null]],"after":"兩輩子都在拿身子換情報。這一回換的是你的命，所以我不覺得髒。"}],"lvzhi":[{"lv":null,"t":"椒房密酌","d":"深夜椒房殿遣散了所有宮婢，只留兩盞銅燈。呂雉換上一襲半敞領口的絳紅深衣，豐滿胸乳在燭光下若隱若現，親自替你斟滿關中烈酒，眼底翻湧著壓不住的佔有與殺氣：「{b}近來替你分憂不少？連夜裡都留她在書房說話……夫君，別忘了當年是誰陪你從破塔走到今日，也別忘了戚夫人是怎麼死的。」","c":[["仰頭飲盡烈酒，扣住她的腰將她按在膝上沉聲道「正宮與江山，從來無人能替妳」",null],["伸手拉攏她滑落的衣襟，笑著留宿椒房殿共飲至天明",null],["公事公辦稱六宮皆有功勞，令她眼底溫度驟然跌進冰窖",null]],"after":"燭火被她反手揮滅時，酒盞翻倒在案上，酒液順著桌沿滴落。天亮宮婢推門收拾，只見滿地凌亂深衣、榻褥上一片濕濡水痕，以及呂雉靠在枕邊、唇角那抹饜足而森冷的笑。"},{"lv":null,"t":"全城耳目","d":"你意外查出書房奉茶的內侍、殿外輪值的宿衛，甚至連{b}寢殿裡的掌事宮婢，全在不知不覺間換成了長樂宮的死士！呂雉緩步走入，面容平靜得令人發寒：「你太容易被女人的眼淚軟化。唯有把你身邊的每一口茶、每一夜行蹤、甚至{b}哪天來月事都捏在本宮手裡，我才放心沒有人能背叛你，也沒人能把你從我榻上搶走。」","c":[["直視她深不見底的雙眸，竟笑著默許這份令人窒息的鐵血掌控",null],["溫言肯定她的護主之心，但下令撤回安插在別殿的眼線",null],["震怒於她竟架空君王內廷，雷霆撤換心腹並罰禁見三旬",null]],"after":"天運者，這世上只有我呂雉會用最毒、最穩的手段，把你的江山、你的命和你這副身子，死死鎖在椒房殿裡。"},{"lv":null,"t":"高后死守","d":"你親率主力遠征在外，主城卻突遭敵軍與城內叛將裡應外合夜襲！呂雉未穿軟緞，直接披上玄鐵重甲、親提天子劍登臨城樓，當場將三名通敵校尉斬首掛旗、令全城丁壯血戰三日三夜死守燈塔。待你凱旋破圍，滿身血污、臉頰沾著敵血的她只在你面前卸下鐵甲，裡衣已被汗與血浸透：「只要本宮還喘著氣，就絕不讓任何人動夫君的家業一根毫毛！」","c":[["翻身下馬當著三軍之面緊緊擁她入懷，宣告她是你唯一的逆鱗與共主",null],["親手替她拭去臉頰與劍上血跡，許諾往後內廷外朝皆與她共掌",null],["重賞長樂宮死士，今夜推掉一切軍務只陪高后痛飲慶功",null]],"after":"這天下誰都能背叛你，唯有我呂雉不會。……把門關上，替本宮把這身沾血的濕衣剝了，今晚我要聽你說謝謝。"}]}},"persona":{"diaochan":{"desire":"不再當任何男人手裡交換的籌碼，要一個她自己挑的、敢替她殺人的男人。","fear":"被心愛的人用完就送走，像當年王允把她送給董卓、董卓死了她又被當戰利品轉手。","pride":"一張臉、一支舞、幾滴眼淚，就讓天下第一猛將親手捅死了自己的義父。","face":"嬌媚溫順、八面玲瓏，對誰都笑三分，笑得恰到好處，讓人以為她好拿捏。","back":"夜裡睡不著，一個人坐在沉水香爐前發呆；卸了妝的臉冷得嚇人，她最怕的是自己其實從來沒被誰真心要過。","loveWay":"把你的喜好、你的仇人、你身邊每個女人的底細都摸透，替你擺平前朝，也替你清掉後宮。","hateWay":"從不當面翻臉。笑著布局，讓情敵先失名聲、再失寵、再失命，死的時候還以為是別人害的。","scheme":"借刀殺人、挑撥離間、收買宮婢、栽贓私通，該哭的時候哭，哭完了人就沒了。","weak":"看穿她所有把戲，還是把她抱住，說一句：「在我面前，妳不用演。」","heart":{"相愛":["他今天喝了我溫的梅花釀，眉頭鬆了。這暖閣總算有一點家的味道。","兩輩子都在替別人笑，只有在他身邊，這笑是真的。","前朝那幾個老東西又在找他麻煩？明天我去會會他們的夫人。"],"迷戀":["他才剛走，連這爐沉水香都淡了。","他愛吃什麼、皺眉是什麼樣子，我全記下了——記得比當年記董卓的死期還清楚。","想織一張網，把他留在這間屋裡，哪也不准去。"],"深愛":["只要他坐得穩這片江山，再讓我進一次郿塢那種虎狼窩，我也去。","前朝那幾派，我已經替他收拾了一半——該閉嘴的都閉嘴了，有一個再也開不了口。","他沒把我當棋子。這份情，我拿命還。"],"沉淪":["別去看那些無趣的女人……她們哪個懂他一個眼神？","今晚他敢去別的院子，我就赤著腳去攔，跪著求也認了。","我玩了一輩子人心，怎麼偏偏對他吃起醋來？可笑。"],"病態":["每個靠近他的女人，我連她乳母叫什麼都查清楚了。誰敢搶，我讓她身敗名裂，再讓她死得沒人敢收屍。","這一局是專為{b}布的。明天她在夫君面前，百口莫辯。","你是我兩世流離換來的，就乖乖待在我織的網裡。網破了，我們一起死。"],"絕對":["兩世流離，只換你一個人。沒有你，這世界燒了也罷。","別放開我的手。我的命、我的計、我的身子，全是你的。","誰敢把你從我手裡搶走，我就把董卓、呂布那一齣，在這後宮再演一遍——這回我親手遞刀。"]},"act":{"相愛":[{"d":"貂蟬在暖閣新換了沉水香，親手溫一壺梅花釀，配兩碟點心，端著穿過半座城送進你書房，袖口還沾著灶灰。","say":"批了一整天，喝一口。不喝我就坐這裡不走。","eff":null},{"d":"替你整理外袍時，貂蟬在你衣領內側抹了一點她身上的香，指尖故意在你喉結上停了一下。","say":"今天議事，誰聞到這味道，就知道你是誰的人。","eff":null},{"d":"月下，貂蟬只穿一層薄紗為你跳水袖舞，跳到汗濕了鬢角，最後一個旋身跌坐在你腿上。","say":"這支舞從前跳給董卓、跳給呂布。現在，只跳給你。","eff":null}],"迷戀":[{"d":"你隨口提過的江南小吃，貂蟬全記下了，盯著小廚做了一整桌，做壞的那幾盤她叫人全倒進了豬圈。","say":"嚐嚐，跟你記得的一不一樣？不一樣我明天換廚子。","eff":null},{"d":"你午睡時，貂蟬伏在床邊一筆一筆描下你的睡臉，摺好塞進貼身的錦囊，貼著心口放。","say":"睡著的你不防人。我真想看一輩子。","eff":null},{"d":"長廊擦肩時，貂蟬故意掉下一方繡並蒂蓮的絲帕，帕子上還帶著體溫，她回頭一笑。","say":"帕子掉了。今晚親自送回暖閣——別讓宮婢送，我不收。","eff":null}],"深愛":[{"d":"兩名重臣在朝上撕破臉。貂蟬當夜設宴，一個灌醉、一個嚇破膽，第二天兩人在殿上互相讓座。","say":"嘴上的仗交給我打，你留著力氣打黑霧。","eff":null},{"d":"貂蟬打聽到荒原商隊藏著私貨，陪商隊頭目喝了一夜酒，天亮時那人簽了賤價契約，國庫多了三倉軍糧。","say":"他想摸我的手，我讓他摸了。換三倉糧，划算。","eff":null},{"d":"戰事失利，你一夜沒睡。貂蟬不說話，把你的頭按在自己胸口，指頭一下一下撫平你的眉心，直到你睡著。","say":"在我這裡不用撐著。天塌了，我先替你頂一會兒。","eff":null}],"沉淪":[{"d":"聽說你今晚要去{b}殿裡，貂蟬赤腳追出來，在迴廊上拽住你的腰帶，眼眶通紅，當著一排宮人的面跪下了。","say":"今晚別去她那兒……我不設局了，我只要你抱我。","eff":{"love":null,"_fa":null,"mood":null}},{"d":"茶會上，貂蟬笑著說了兩句閒話，{b}和另一位夫人當場為座位翻臉，茶盞摔了一地，{b}的手被碎瓷割得見骨。","say":"哎呀，姐妹們別動氣……都怪我多嘴。","eff":{"love":null,"rel":[[null,null,null]],"rumor":"今天茶會上{b}當眾發瘋砸杯子，手都割爛了；倒是貂蟬，從頭到尾端坐著勸架。"}},{"d":"{b}送你的那對玉墜，貂蟬拿去砸碎了埋在花盆底下，再把自己串的紅瑪瑙珠掛到你腰上。","say":"那顏色太素，配不上你。紅的好，像血。","eff":null}],"病態":[{"d":"貂蟬買通{b}殿裡的粗使宮婢，剪爛她新裁的舞衣，又在宮外散布她私下咒罵君王。那宮婢事後想告發，第二天被人發現吊在柴房，舌頭沒了。","say":"誰叫她搶你的眼神？我替你挑一挑，誰配留下。","eff":{"love":null,"rel":[[null,null,null]],"mood":null,"rumor":"宮裡都在傳{b}私下咒罵天運者，舞衣被剪爛，她殿裡還吊死了一個沒有舌頭的宮婢……"}},{"d":"暖閣暗牆上，貂蟬用硃砂記下你這一個月在每位夫人處待了多久、賞了什麼，密密麻麻全是紅圈，有幾個名字被劃了叉。","say":"分走你的每一個名字，我都記著。打叉的，是快沒了的。","eff":{"love":null,"mood":null}},{"d":"深夜，沉水香濃得嗆人。貂蟬反手落了門閂，勾住你的脖子，在你耳邊笑，手指卻冰涼。","say":"這張網是專為你織的。你乖乖待著，別再看別人——不然我就把她們的眼睛挖出來，讓她們也看不了你。","eff":null}],"絕對":[{"d":"敵酋設鴻門宴要殺你。貂蟬獨自入營三日，陪酒陪睡，套出全部伏兵布防，臨走割了敵將的喉，渾身是血地回來。","say":"最後一場連環計，是替你演的。兩輩子都在演，只有愛你這件事是真的。","eff":null},{"d":"貂蟬把她苦心經營多年的暗線名冊——收買過誰、毒死過誰、誰的把柄在哪——整本交到你手上，然後卸了妝撲進你懷裡。","say":"我不留退路了。哪天你要殺我，這本冊子就是罪證。","eff":null},{"d":"被你冷落多日，貂蟬在滿屋嗆人的沉水香裡對著銅鏡一遍遍練笑，笑到嘴角抽筋，眼淚一直往下掉，把胭脂沖成兩道紅痕。","say":"是不是我笑得不夠好看了？你為什麼不回頭……","eff":{"love":null,"mood":null}}]},"mood":null,"react":{"pamper":["你這樣寵我，我會被寵壞的——壞了你可別後悔。","再抱一會兒。我就喜歡被你寵得無法無天。"],"scold":["（眼眶一下紅了，咬著嘴唇）是我不好……你罵完了，別不理我。","為了別人這樣兇我？好，我記住了。"],"ignore":["你連看我一眼都懶了？","行。你不看，我就回暖閣守著那爐冷香，看誰先熬不住。"],"punish":["禁足？降位？連一句話都不讓我說？","好……原來天下的男人，到頭來都一個樣。"],"forgive":["肯原諒我了？今晚我親手斟酒賠罪——喝醉了不准走。","我就知道，你最捨不得的還是我。"],"other":["你跟{b}姐姐真恩愛，我在旁邊看得牙都酸了。","剛從{b}床上下來，身上還是她的味道，就來我這兒說好聽話？"],"caught":["（輕嘆一聲，淚光一閃又收回去）被你看穿了。可我不設局，你什麼時候才只看我？","局是我設的，人是我叫人弄死的。要罰，就罰我一輩子關在你懷裡。"],"win":["這滿宮上下，最懂你的，終究是我。","贏了要有賞——今晚你不准回書房。"]}},"lvzhi":{"desire":"將前朝與內廷的生殺大權、兵符印信與繼承血脈死死攥在掌心，確保自己永居至尊共治之位，凡威脅者一律斬草除根。","fear":"重演楚營二十八個月淪為階下囚的奇恥大辱，或像大漢晚年般眼睜睜看著年輕賤婢憑一張媚臉騎到自己頭上爭奪江山。","pride":"大漢臨朝稱制十六載的高后，長樂宮鐘室誅韓信、洛陽醢彭越、南北軍盡歸諸呂，連冒頓單于的羞辱都能忍下再反噬。","face":"端莊森嚴、喜怒不形於色，理政井井有條，外人眼中是最能替天運者穩住糧稅與後方的定海神針。","back":"骨子裡極度殘酷記仇、毫無慈悲。對她而言，灌落胎藥、剃髮黥面、斬人手足丟進茅廁，不過是清理雜草的尋常政務。","loveWay":"用最血腥、最徹底的手段替你掃平前朝反骨與後宮妖孽，哪怕背負千古毒婦罵名也面不改色，並在榻上以同樣強勢的佔有慾將你鎖死。","hateWay":"從不玩小打小鬧的口舌之爭；動手便是斷人手足、灌啞藥、毀容落胎、滿門抄斬，還要把慘狀擺在六宮面前殺雞儆猴。","scheme":"一面以休養生息與鐵腕理政讓你離不開她，一面暗中安插呂氏黨羽與內廷耳目，隨時準備在你心軟或失勢時接管全城。","weak":"世上沒有能讓她悔改軟化的弱點；唯一能壓住她的，只有展現比她更冷酷的帝王手腕，並承認她無可取代的共治地位。","heart":{"相愛":["這座燈塔的規矩還是太軟。既然你把內廷交給我，那些不知天高地厚的丫頭便由本宮替你清乾淨。","前朝那幾個老將功高震主，你若拉不下臉動手，長樂宮的鐘室隨時替你備著。","男人的甜言蜜語最靠不住，唯有實實在在握在掌心的兵符與印信，才永遠不會背叛本宮。"],"迷戀":["你比劉季有魄力，也比他更識貨——這座江山，理應由你我夫妻共掌，輪不到旁人插嘴。","{b}這幾旬往書房跑得太勤了。看來得找個由頭，讓她徹底閉上那張討巧的嘴。","只要你還需要本宮替你幹髒活，這座後宮的生殺大權就永遠逃不出椒房殿。"],"深愛":["我替你背負所有毒婦罵名，替你斬盡叛臣與礙眼賤婢——這便是我呂雉愛一個男人的方式。","別跟本宮講什麼仁義道德。當年我忍了二十年才換來大漢安穩，誰敢動你的江山或我的位子，我便叫她生不如死！","我愛你，所以我絕不容許任何女人用眼淚、嬌喘或肚子裡那塊肉來軟化你的骨頭。"],"沉淪":["聽說{b}胞宮有孕了？哼，這座城的繼承血脈只能聽命於椒房殿，她腹中那塊肉，絕留不得。","你今晚又宿在{b}榻上？好得很……等哪天你親征出城，本宮定教她嚐嚐髡髮舂米與人彘的滋味！","你越是護著那些只會搖腰獻媚的狐狸精，本宮便越要讓你知道，誰才是真正能壓死這座城的女人。"],"病態":["既然你總愛心軟優柔，不如這前朝與後宮全由本宮臨朝稱制罷，你只需安穩待在椒房殿裡，夜夜陪我便是。","把{b}身邊所有宮婢全換成我的死士，她的湯藥、她的子室、她的命，從今日起全攥在本宮掌心。","人彘之刑為何能震懾天下？因為只有把活生生的美人剁成連親兒子都不敢看第二眼的肉團，其他蠢貨才會真正懂事！"],"絕對":["這天下我只認你一個夫君，但也絕不會為你交出半分權柄。你若狠，我便陪你屠盡歸墟；你若軟，我便替你執刀！","誰敢從我手裡分走你的江山、血脈或一夜溫存，無論她是哪朝名姝，本宮都必將她挫骨揚灰、永不悔改！","我們本就是同一類人——踏著屍山血海登頂的王者。別裝什麼慈悲了，把生殺大權和這副身子都交給本宮吧。"]},"act":{"相愛":[{"d":"呂雉未經通傳便在永巷處決了兩名貪墨糧銀的少府管事，將沾著血點的家產清冊平靜地擺到你書案上。","say":"前朝走律法太慢，本宮替夫君先斬後奏了。這筆糧銀已全數追回公庫。","eff":null},{"d":"呂雉整理出前朝所有功臣與後宮夫人的私密把柄，親自溫了一壺關中濁酒端到你面前，指尖輕壓在你的手背上。","say":"御下之道不在恩賞，而在捏住他們的七寸。這卷密冊，夫君收好。","eff":null}],"迷戀":[{"d":"呂雉在內廷茶會上當眾用冰冷得能刮下霜的語氣敲打{b}，目光緩緩掃過她的臉蛋與四肢，暗示她若不知進退，下場會比永巷慘烈十倍。","say":"妹妹生得這般細皮嫩肉，可得好好護著這張臉、這雙眼和這副身段啊。","eff":{"love":null,"rel":[[null,null,null]],"mood":null,"_mb":null}},{"d":"前朝一名剛直御史當庭彈劾呂雉干政，隔日便在城郊「意外」墜馬斷腿、被迫致仕，呂雉聽報時連眼皮都未曾抬一下。","say":"路滑摔斷了骨頭罷了，夫君何必替一個管不住嘴的老糊塗費心？","eff":{"love":null,"pop":null,"rumor":"彈劾呂雉的御史隔日便詭異墜馬斷腿，滿朝文武頓時噤若寒蟬！"}}],"深愛":[{"d":"你猶豫是否要處置一名手握兵權的降將，呂雉竟直接偽造你的手諭將其誘入長樂宮偏廳，令武士以竹槍刺殺，事後平靜地呈上首級與虎符。","say":"當年韓信也是這樣死在長樂宮鐘室的。你下不了的狠手我替你下，千古罵名我替你扛。","eff":{"energy":null,"love":null,"pop":null,"rumor":"降將應召入長樂宮後屍首分離，滿城皆知是呂雉先斬後奏、鐵腕奪回兵權！"}},{"d":"呂雉雷霆整頓六宮，將三名私下嚼舌根的宮婢當眾杖斃於庭中，又命人將帶血的刑杖立在宮門示眾，全宮頓時鴉雀無聲。","say":"不見血，這群賤奴永遠記不住誰才是真正的主人。","eff":null}],"沉淪":[{"d":"呂雉趁你出城巡防，把受寵的{b}鎖進陰濕地牢斷水斷糧兩日，又命老宮媼剝去她外衣、拿燒紅的烙鐵在她臉側與胸前比劃恐嚇，把{b}逼得失禁崩潰、涕淚橫流。","say":"本宮還沒真的在她臉上黥字、還沒在她胸口烙印，只是讓她提前嚐嚐恃寵生嬌的代價罷了。","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"_mb":null,"rumor":"聽說呂雉趁天運者不在，將{b}關進暗牢以烙鐵威嚇至崩潰失禁，六宮聞之魂飛魄散！"}},{"d":"聽聞{b}近日疑有身孕或得你極度偏愛，呂雉暗中買通藥房在其補湯裡摻入極烈的紅花與麝香寒藥，意圖徹底絞毀她的胎室、斷絕其生機。","say":"這座城池的骨血與恩寵，豈容一個不知深淺的賤婢染指？落了胎，才省事。","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"mood":null}}],"病態":[{"d":"呂雉在椒房殿暗室裡當著你的面展示一隻被剪斷雙翼、刺瞎雙眼、拔去舌頭的籠中白鳥，血水滴在青磚上，她的目光卻死死釘在{b}殿閣的方向。","say":"夫君瞧這鳥兒多乖巧？當年戚夫人若是早點學會閉嘴，也不必在茅廁裡當那無手無腳、無眼無耳的「人彘」呢。","eff":{"love":null,"rel":[[null,null,null]],"mood":null,"rumor":"呂雉在殿中公然剖鳥重提「人彘」舊事，{b}聽聞後嚇得整夜高熱抽搐！"}},{"d":"呂雉暗中把城防南北軍校尉與少府總管全數換成自己的死士，甚至在你偶感風寒時直接坐進正殿珠簾後代你批閱章疏、發號施令。","say":"夫君身子乏了便安心躺著，這座城有本宮臨朝稱制代管，絕不會出半分差池。","eff":null}],"絕對":[{"d":"你明令保下某位觸怒她的重臣，呂雉當面領命，當夜卻派死士抄斬對方滿門、連犬馬不留，次日依舊端著溫熱茶盞平靜地坐在你案前。","say":"本宮說過，只要我活著一天，就絕不留任何威脅在你身邊。你要罰便罰，但我絕不後悔！","eff":null},{"d":"呂雉將象徵長樂宮最高暗網的玄鐵虎符與一盞鴆酒並排推到你面前，解開領口露出鎖骨下方一道舊疤，眼神冷冽而熾熱。","say":"這江山是我陪你一刀一血打出來的。要麼與我共掌生殺、殺盡礙眼之人；要麼，你現在就賜死本宮！","eff":null}]},"mood":null,"react":{"pamper":["收起這套哄小丫頭的軟話，真要偏愛本宮，就把內廷生殺大權與少府印信全交過來。","哼，算你還分得清誰才是真正能替你守江山的女人。今晚留下，別去別處。"],"scold":["罵我毒婦？這座城若是沒我這個毒婦替你立威殺人，早就被流民和降將拆成柴火了！","你儘管訓斥，反正下回遇上礙眼的賤人，本宮照殺不誤！"],"ignore":["冷落本宮？好得很，你且看看我這雙手空下來後，會去收拾哪座殿閣！","（冷笑）劉季當年也愛躲著我去找戚夫人聽楚舞，後來她的下場你應該讀過史書吧？"],"punish":["禁足？降位？天運者好大的威風！可你別忘了，你關得住我的人，關不住椒房殿滿城耳目！","罰吧，今日你給我的每一分羞辱，本宮都會十倍討回在{b}的皮肉與骨頭上！"],"forgive":["原諒？本宮從不覺得自己有錯，何須你原諒！不過是前朝後宮離不開我，逼得你不得不放人罷了。","既放本宮出來了，那便別再攔著我清君側。"],"other":["剛從{b}那賤婢榻上下來？衣袍上那股廉價脂粉與汗臭味真教人作嘔。","你儘管捧著她，捧得越高，將來被我剝皮削骨丟進茅廁時才越好看！"],"caught":["是我下的手又如何？本宮從不屑於像小丫頭那樣哭著跪地求饒！要殺要剮隨你，想聽我懺悔？做夢！","沒錯，就是本宮要絞毀她的胞宮、毀她的臉！若非你攔得快，她此刻已經是個人彘了！"],"win":["意料之中。在這座宮裡，還沒有誰鬥得過大漢高后。","贏了便該斬草除根，留著一口氣只會徒增禍患。"]}}},"valTalk":{"diaochan":{"favHi":"（眼波一轉，笑著貼過來）你這樣偏我，不怕前朝那群武將又為我拔刀？","favLo":"色衰愛弛，深宮常事。可你別忘了，我從來不是靠一張臉活到今天的。","infHi":"前朝的將怕我，內廷的人跪我。這盤棋，總算輪到我執子了。","infLo":"（搖著團扇淡淡一笑）失勢正好藏鋒。連環計，從來都是在最不起眼的時候布下的。","ambHi":"我再也不當被人送來送去的禮物。我要站在能定人生死的地方。","rankUp":"謝夫君抬舉。前朝後宮，誰不服，我替你一個一個收拾。","rankDown":"（眼神一暗，福身笑著）降就降吧。往後武將鬧翻天，別來求我。","hedonHi":"這世道撐不了幾年。守城太累，不如跟我在花廊裡醉到天亮，醉死了也算快活。","tyrannyHi":"以柔克剛太慢。敢算計我的，讓他們全家自己互砍，砍到最後一個，我再補一刀。","bothHi":"歌舞底下埋著屍骨。夫君，你我這場末世連環局，比三國還瘋。"},"lvzhi":{"favHi":"（冷笑微斂，指尖替你整平衣領，順勢滑進襟口）這滿宮女人裡，終究還是本宮最合你心意——放心，外頭那些雜碎我會替你掃乾淨，今夜這椒房暖帳便歸你了。","favLo":"冷落本宮？呵，男人的寵愛本就比露水還短，好在椒房殿的兵權與印信，比你的心實在得多——何況這宮裡又不缺像審食其那般懂事的人。","infHi":"如今前朝六部與南北軍半數皆聽本宮號令，天運者，這座江山沒我呂雉可撐不住。","infLo":"（指尖冰冷地叩著玉案）一時失勢又如何？當年楚營二十八個月人質本宮都熬過來了，遲早連本帶利連人帶命討回來。","ambHi":"區區妃嬪之位豈能困住大漢高后？總有一日，這正殿上的珠簾會為本宮而垂！","rankUp":"晉位不過是名實相符罷了，往後這六宮的生殺與規矩，更得由本宮說了算。","rankDown":"（雙目陰沉如毒蛇，唇角緩緩勾起）敢降本宮的位分？好得很，你且看這筆帳本宮將來拿誰的血來算！","hedonHi":"成日沉溺溫柔鄉與酒池也挺好——反正你越荒唐無度，這前朝的實權與兵符就越順理成章歸本宮管。","tyrannyHi":"酷刑、菹醢與人彘才能教這群賤人懂規矩！沾在手上的血越厚，這把椅子才坐得越穩！","bothHi":"一面酒色荒淫、一面血洗異己……哈哈，這座徹底腐爛卻又死寂無聲的血城，真是本宮最稱心的傑作！"}},"inter":{"act":{"diaochan":{"walk":["（挽著你的手臂，故意走得很慢）你肯陪我走一段，比賞我一箱珠子還難得。","這條長廊我從前一個人走，數著步子算計人。現在挽著你，我只想它長一點。"],"meal":["這幾道點心我盯著小廚做的，做壞的都倒了。你嚐，不好吃我明天換人。","（張嘴接過你夾的菜，咬著筷尖不放）你夾的，連心口都是甜的。"],"art":["這支水袖舞我偷練了半個月，腳底磨破了兩回。你要是敢看別處，我就停。","一舞傾城又怎樣？我這輩子讓人傾倒過太多回，只想倒在你一個人眼裡。"],"dress":["（仰著臉讓你點唇，呼吸噴在你手上）手別抖……靠這麼近，我的心跳你都聽見了吧。","你親手插的金步搖，明天滿宮的人看了，牙都要咬碎。"],"drill":["刀槍太重，我拿不動。不如你教我——不對，我教你，怎麼一眼看穿一個人想殺你。","比武我認輸。可論在這間屋裡過招，你未必贏得了我。"],"court":["哪個大臣吃軟、哪個要敲打、哪個收了誰的錢，我都替你理好了，寫在這張紙上。","前朝的暗流交給我。你坐穩了，誰想掀你的桌子，我先剁他的手。"],"tour":["出城真好。有你在身邊，連荒原上的風都不割臉了。","跟著你，去哪都行。繁華也好，屍山也好，我都看過。"],"comfort":["（一頭撞進你懷裡，抓著你的衣襟不放）你來了，我這顆心才落回去……再抱一會兒。","謝謝你肯看我這副不值錢的樣子。這世上看過的，就你一個還活著。"]},"lvzhi":{"walk":["禁苑深處耳目稀少，陪本宮走走，正好把下旬前朝的人事名單過一遍。","這滿城上下都在算計權位，唯有與你並肩緩行時，本宮這根繃了二十年的弦才肯鬆開半寸。"],"meal":["關中烈酒配炙羊肉，最合本宮胃口。來，夫君陪我滿飲這碗——不許推辭。","能讓大漢高后親手替你夾菜斟酒，夫君，你可要把這份偏愛記進骨子裡。"],"art":["本宮不愛那些無病呻吟的酸腐詞句，來下一盤圍棋，看看咱們夫妻誰的屠龍局更狠！","這手棄子斷腕甚合我意！唯有與你對弈，本宮才覺棋逢對手。"],"dress":["（仰起臉任你描眉，目光卻直勾勾鎖著你）讓一城之主親手替本宮畫眉插釵，這份體面，本宮甚是受用。","鏡裡這副既壓得住朝堂、又肯為你鬆開衣襟的模樣，這世上唯有夫君看得到。"],"drill":["論御下之術與權謀殺伐，來，讓本宮看看夫君近來學到了幾成狠辣！","很好，不像當年劉季那般優柔寡斷。你有資格站在本宮身側，共分山河。"],"court":["這批官員的私產、把柄與暗通記錄本宮全摸清了，夫君只要蓋印，就能把他們捏死在手心。","前朝的刀交給你，後宮與暗網的毒交給本宮，咱們夫妻便是這座城最破不開的鐵壁。"],"tour":["出巡正好親眼查驗各處分城守將有無異心，紙上奏章從來信不得。","看著這片由你我夫妻一手打下、又一刀一血鎮穩的基業，本宮胸口總算暢快了幾分。"],"comfort":["本宮還沒軟弱到需要誰來哄……但你既來了，便坐近些，陪我喝完這壺烈酒。","這世上人人怕我、罵我、恨不得食我肉，唯獨你敢這樣抱緊我這副冷硬身子……夫君，別負我。"]}},"ask":{"diaochan":[{"q":"世人都說貂蟬靠臉和謊話玩弄男人。你夜夜抱著我的時候，懷疑過我是真是假嗎？","c":[["分得清——妳靠在我身上睡著的時候，心跳騙不了人","（她眼神猛地一顫，慢慢把臉埋進你胸口）……你是第一個看穿我還不跑的人。",{"_aff":null,"love":null,"trait":null}],["就算是戲，我也陪妳演一輩子","（她掩著嘴笑，眼底卻亮了一下）這話比直說還要命。",{"_aff":null,"love":null,"trait":null}],["防人之心不可無，妳不背叛我，真假無所謂","（笑意一冷，手指從你掌心抽回）懂了。我在你眼裡，就是個解悶的玩意兒。",{"_fa":null,"love":null,"trait":null}]]},{"q":"如果明天有個敵酋點名要我去他帳裡，用我換一場不打的仗，你讓不讓我去？","c":[["不讓。江山我自己打，輪不到拿我的女人去換","（她眼眶一下濕了，死死抱住你）……王允當年，一句都沒對我說過。",{"_aff":null,"love":null,"trait":null}],["我扮成隨從跟妳一起去，誰碰妳我當場剁了他","（她破涕為笑）那可好，我們夫妻倆一起去把那蠻子玩死。",{"_aff":null,"love":null,"trait":null}],["能不戰而屈人之兵，值得考慮","（她垂下眼，聲音冷得像冰）明白了。我還是那枚最好用的棋子。",{"_fa":null,"love":null,"trait":null}]]},{"q":"你覺得這後宮裡，哪個女人最難對付？","c":[["誰都好對付，就妳一撒嬌，我半點招架不住","（她笑著用指尖戳你額頭）嘴這麼甜，今晚的香算白點了——你別想睡。",{"_aff":null,"love":null,"trait":null}],["各有脾氣，全靠妳替我壓著","你信我，六宮的人心我替你捏在手裡。不聽話的，我讓她自己求去冷宮。",{"love":null,"trait":null}],["還是妳心最深，最摸不透","（笑意一收）你既然怕我，今晚就別來了。",{"_fa":null,"love":null,"trait":null}]]},{"q":"等我老了，跳不動了，臉也皺了，你還會像今晚這樣要我嗎？","c":[["我要的是妳這個人，白頭了也只要妳","（她眼睛亮得嚇人，低頭咬了一口你的手背）記住這句。你敢反悔，我咬斷你的喉嚨。",{"_aff":null,"love":null,"trait":null}],["那時候歸墟早平了，正好一起養花喝茶","聽著真好……我盼那天早點來。",{"love":null,"trait":null}],["還早，想那麼多幹什麼","（她輕輕嘆了口氣）男人的話，果然只管今晚。",{"_fa":null,"love":null,"trait":null}]]}],"lvzhi":[{"q":"當年我陪劉季從沛縣草創打下大漢，替他在家耕田、在楚營受辱二十八個月，換來的卻是他晚年迷戀定陶戚姬、想廢我親兒。夫君，你將來會不會也演這齣戲？","c":[["絕不；妳我同生共死打下的江山，正宮與共治之位永遠只歸妳一人","（她深沉的眼底罕見泛起一絲滾燙，反手扣緊你的五指）記住今晚這句話。你若不負我，本宮便誓死替你殺盡天下敵。",{"_aff":null,"love":null,"trait":null}],["椒房殿的耳目與內廷實權都在妳手裡，我哪敢像劉季那樣昏頭？","（她唇角勾起冷豔而滿意的弧度）識時務者為俊傑，夫君比他聰明多了。",{"_aff":null,"love":null,"trait":null}],["後宮恩寵本就隨心所欲，誰得寵全看各自造化","（她眸光驟然森冷如刀，重重擱下酒盞）好啊，那本宮倒要看看，這宮裡誰有命享那份造化！",{"_fa":null,"love":null,"trait":null}]]},{"q":"前朝清流與史官皆罵本宮殘酷毒辣、不近人情，連親生兒子見了人彘都嚇破了膽。夫君心裡，可也曾覺得我太狠？","c":[["亂世用重典，妳背著千古罵名替我守住底線，我護妳都來不及","（她神色微震，隨即貼近你耳畔低笑）……這滿城上下，唯有你配懂本宮的狠。",{"_aff":null,"love":null,"trait":null}],["不狠如何壓得住這群傲氣英靈？咱們一個唱白臉、一個唱黑臉正好","甚合我意！夫君這份政治默契，天下無人能及。",{"_aff":null,"love":null,"trait":null}],["有些手段確實太過絕情，往後還是留些餘地為妥","（她冷哼一聲，眼底滿是不屑）婦人之仁！等哪天被手下與賤婢反咬斷喉，你便懂了。",{"_fa":null,"love":null,"trait":null}]]},{"q":"若是有一日朝中某位手握重兵的名將功高震主，像當年韓信、彭越一般尾大不掉，夫君打算怎麼處置？","c":[["先與妳密議，明賞暗削、以制衡收其兵符，既穩江山又不失名聲","（她撫掌冷笑）高明！論帝王心術，夫君已比高祖更勝三分。",{"_aff":null,"love":null,"trait":null}],["只要他真心效忠，我便以誠待之，不必急著動刀","過於寬厚雖是隱患，但既是你選的路，本宮便暗中替你把刀磨好盯緊他。",{"love":null,"trait":null}],["直接效法長樂宮鐘室舊事，誘入宮中斬草除根、剁成肉醬以震諸侯","（她挑眉看你一眼，眼底浮出近乎狂熱的欣賞）夠狠！這種髒活交給本宮動手便是，莫污了你的衣袖。",{"_aff":null,"love":null,"trait":null}]]},{"q":"拋開這座孤城與萬千權柄不談，夫君究竟看上了我呂雉哪一點？這宮裡年輕貌美的丫頭可多的是。","c":[["看上妳強橫到能與我並肩扛天，卻又肯在我懷裡解衣承歡","（她罕見地微側過臉，耳尖泛起一抹暗紅，指尖輕掐你的腰側）……油嘴滑舌。但這話，本宮受用了。",{"_aff":null,"love":null,"trait":null}],["唯有妳這般鐵腕與格局，才撐得起這座星盤燈塔的內廷","算你有眼光。能得漢高后輔佐，本就是你天大的造化。",{"love":null,"trait":null}],["畢竟妳是外戚派領袖，娶妳能穩住朝堂勢力平衡","（她眼神瞬間結冰，冷笑推開你的手）很好，原來在夫君眼裡，本宮只是一筆交易。",{"_fa":null,"love":null,"trait":null}]]}]},"visit":{"diaochan":[{"t":"暗遞情報","l":[[null,"夜深，貂蟬閃進書房，反手關門落閂，從胸口抽出一張摺得極小、還帶著體溫的紙箋。"],[null,"{a}這陣子跟幾個商賈走得很近，想私吞下月的絲茶採買。賬我抄來了，她還收了一個商人送的玉枕——那人每晚都從她殿後門進去。"],[null,"妳這消息比暗衛還快。"],[null,"（笑著把紙箋塞進你衣襟裡，手沒抽出來）我見不得有人背著你動手腳。要不要我替你把那商人處理掉？"]],"c":[["收下紙箋，把她攬進懷裡，誇她是最利的一把刀",null],["笑說會暗中查，賞她一杯溫酒",null],["提醒她後宮姐妹別互相咬",null]]},{"t":"撒嬌討香","l":[[null,"貂蟬繞到你身後，手指按著你的太陽穴揉，身子貼著你的背，聲音軟得滴水。"],[null,"聽說庫房收了一匣西域沉水香，聞了好睡。"],[null,"揉這麼殷勤，原來是惦記那匣香。"],[null,"（咬了一下你的耳朵）討厭。燻在暖閣裡，最後還不是你睡在我床上聞。"]],"c":[["當場把香賞她，說今晚去暖閣聞",null],["捏捏她的手心，答應下回商隊來替她留",null],["正色說庫房珍品要留作外交禮，拒絕",null]]},{"t":"紅袖添酒","l":[[null,"雨剛停，貂蟬端著一壺溫熱的梅花釀和兩碟糕點進來，裙襬濕了一截，貼在小腿上。"],[null,"雨一停，我就猜你還趴在桌上沒睡。"],[null,"妳總算得這麼準，正好渴了。"],[null,"（坐到你腿上，自己先喝一口，再湊過來餵你）歇半個時辰。我斟酒，你不准碰公文。"]],"c":[["推開政務，跟她對坐喝到燭火燒盡",null],["喝兩杯誇她貼心，叫她先回房睡",null]]}],"lvzhi":[{"t":"暗網密報","l":[[null,"夜霧森然，呂雉揮退書房外所有宿衛，反手落閂，將一卷沾著蠟封的帛書平穩放到你案前。"],[null,"長樂宮耳目查實，前朝兩名御史正暗中串聯{a}一派，打算在下次朝會上聯名壓制你的新政。"],[null,"這才剛起個苗頭，高后便已把名單與底細全摸清了。"],[null,"（指尖輕點帛書上兩個名字，語氣平淡得像在點菜）夫君只需頷首，明早這兩個不長眼的東西便會「暴病身亡」，絕不污你的手。"]],"c":[["讚許她的鐵腕與遠見，默許她暗中清除障礙穩固大局",null],["收下名單由自己出面制衡，親自替她斟酒致謝",null],["提醒她後宮耳目莫要過度伸手前朝，令她神色轉冷",null]]},{"t":"烈酒醒神","l":[[null,"深夜批閱軍報之際，呂雉親自端著一壺溫熱的關中老酒與兩碟炙肉步入書房，玄色外袍下只著一件鬆鬆繫著的絳紅裡衣。"],[null,"連熬兩夜、臉色發青，再這般硬撐下去，還沒踏平歸墟就先累垮在書案上了。"],[null,"沒想到大漢高后還會親自替人送宵夜。"],[null,"（坐到你身側，替你斟滿酒盞，手指順著你的手背緩緩摩挲）少廢話。喝完這碗烈酒，隨本宮回椒房殿歇息——今晚不准再碰竹簡。"]],"c":[["微笑舉杯與她對飲，放下卷宗攬著她共返椒房暖帳",null],["一飲而盡謝過她的照料，請她先回椒房殿安歇",null]]},{"t":"索要權威","l":[[null,"午後呂雉端莊走進書房，目光精準落在案上那份少府珍玩與月例分配清冊上。"],[null,"夫君，這旬商隊進貢的玄金玉器與西域錦緞，理應優先撥入椒房殿，方顯內廷正統威儀。"],[null,"高后親自開口，看來是對那批玄金珍玩勢在必得了？"],[null,"位分與排場相稱，六宮才懂得敬畏。夫君不會連這點體面都吝嗇吧？"]],"c":[["大方賜下禮物與全套玄金珍器，令她滿意頷首",null],["笑著答應讓她先挑一半，其餘按例分發六宮",null],["堅持按舊例平分以示公允，令她冷哼一聲拂袖離去",null]]}]},"wish":{"diaochan":[{"t":"沉香暖禮","ask":"商隊新到一批西域奇香和珠寶。挑一樣送我——挑錯了，我可要生氣。","cond":null,"n":null,"days":null,"done":"（把禮物貼在臉上，眼睛彎起來）你眼光真好。我要壓在妝奩最底下，死了也帶進棺材。","fail":"你把我那點心願忘了？行，我記著。","eff":null},{"t":"夜訪暖閣","ask":"暖閣新換了香。這幾旬你多來陪我，不許爽約——爽約一次，我就讓你一個月睡不著。","cond":null,"n":null,"days":null,"done":"這幾夜，是我這輩子睡得最沉的。宮婢早上進來，都不敢抬頭看床。","fail":"等了這麼多夜，連個影子都沒有。沉水香留不住你，那我換別的東西留。","eff":null}],"lvzhi":[{"t":"驛道耳目","ask":"欲控天下必先通耳目。夫君，把驛站建起來，主城與分城的風吹草動方能盡入你我掌中。","cond":null,"n":null,"days":null,"done":"快馬已備、密道已通。從今往後，這片歸墟誰也別想瞞過咱們夫妻的眼睛！","fail":"消息閉塞最易滋生叛亂，夫君這樁事辦得太慢了。","eff":null},{"t":"立威揚兵","ask":"近日外敵與周邊軍閥蠢蠢欲動，夫君須連勝三場立下鐵血威名，免得宵小生出輕視之心！","cond":null,"n":null,"days":null,"done":"殺得乾淨俐落！這般鐵血威名，才配做本宮選中的男人！","fail":"久戰未立威，難免讓前朝某些長了反骨的傢伙蠢蠢欲動。","eff":null}]},"bday":{"diaochan":{"remember":"（眼睛一亮，撲上來掛在你脖子上）連我生辰都記得……今晚留下，不准走。","forget":"燈點了一整夜，蠟淚流了一桌。原來你早忘了。","gift":"這份禮真襯我。你果然知道女人想要什麼——尤其是我這種女人。"},"lvzhi":{"remember":"（眼底冷霜罕見融開三分，接過你的手）夫君有心了。能與你對飲共度生辰，比當年未央宮裡百官虛偽的朝賀稱心多了。","forget":"連椒房殿正主的生辰都記不住，夫君這幾旬是被哪個賤婢灌了迷湯？","gift":"甚好，這份生辰禮夠氣派，配得上大漢高后的身價。本宮收下了。"}},"anniv":{"diaochan":["又一年了。謝謝你讓我不用再被人送來送去，有了一間自己的暖閣。","今晚紅燭點到天亮。洞房那夜你怎麼對我的，今晚再來一遍。"],"lvzhi":["風雨同舟又一載，這座城池與你我夫妻的根基已釘得固若金湯。","來，滿飲這杯合巹烈酒——往後歲月，這江山與你這個人，皆歸本宮獨守。"]},"jealous":{"diaochan":["你剛從{a}姐姐房裡出來吧？眼神還軟著呢，看得我牙酸。","{a}剛才在你耳邊說了什麼？讓你魂都丟在她那兒了。","你身上全是{a}的味道。今晚我得點三爐香才蓋得過去——蓋不過，我就把她燒了。"],"lvzhi":["剛從{a}那裡過來？夫君這幾日倒是格外偏寵她啊，連她身上的香粉味都帶進椒房殿了。","帶著{a}的氣息踏進本宮寢殿，夫君這是在試探高后的氣量，還是嫌她活得太安穩？","去淨手更衣吧。本宮最見不得自己榻上沾染別的女人的味道。"]}},"edict":{"diaochan":{"賑":["開倉放糧。流離失所是什麼滋味我嘗過，一碗粥能讓人記一輩子。","發糧時盯緊孤兒寡婦。誰敢剋扣，砍了手掛在粥棚上，百姓才知道這城是誰在護。"],"徵":["內廷的脂粉舞樂開銷大了，向城裡富商加徵脂粉稅。誰喊窮，查他的賬。","連環計要錢鋪路。這筆稅收進來，正好拿去買前朝那幾張嘴。"],"截":["這幾封挑撥的奏摺全截下來燒了，別拿這種東西髒了夫君的眼。","武將爭風吃醋的密報先扣在我這兒，我親自去收拾——收拾完，就沒人再爭了。"],"兵":["調一隊精銳禁軍守內廷，夜裡誰敢亂走，先綁了再問。","派人盯緊那幾個桀驁的猛將。誰長了呂布那種反骨，我先讓他身邊的女人遞刀。"],"練":["今天我去校場獻舞勞軍。看過我跳舞的兵，殺黑霧會比平時狠三分。","校場殺氣太重，賞全軍美酒三十罈，讓他們記住是誰賞的。"],"土":["修閉月花廊和觀星水榭，夫君打完仗，總得有個地方醉。","重修舞樂坊。這座城要能打，也要讓人捨不得死。"],"祭":["月圓夜我主持拜月祭天。拜的是月，求的是夫君和這座城的命。","焚香起舞告天：這亂世早點完，別再拿女人當棋子——要拿，也輪到我來拿。"],"刑":["別以為我只會笑。在背後害我的，拖進暗室，先拔指甲，再一根一根敲斷手指，問出主使為止。","私設刑堂審那個造謠的細作。烙鐵燒紅了再問，問完挖了眼睛丟回他主子門口。"],"官":["把幾個識時務、又敬我的文武提進中樞。","安插我的女官管內廷文書。誰想算計我，我得比他先知道。"]},"lvzhi":{"賑":["開倉放糧！記住，讓每個領粥的流民都聽清楚，這碗救命米是長樂宮椒房殿賞的！","賑災可以，但所有糧袋全給本宮印上呂氏徽記，民心該向著誰，底層百姓心裡得有數。"],"徵":["內廷與暗網開銷浩大，向城中富商豪族加徵三成稅銀，哪家敢哭窮藏私直接抄家！","天下財賦本就該供養掌權之人，這筆稅銀全數直入椒房私庫，少府不必過問。"],"截":["前朝那幾卷彈劾本宮專權的章疏全扣下來投入火盆，別拿酸儒廢話煩天運者。","從今日起，所有軍政急報先呈長樂宮過目，本宮朱批允准了再送去書房！"],"兵":["傳本宮懿旨，調兩千玄甲南北軍宿衛進駐內廷，誰敢妄動一步，就地格殺！","虎符？本宮掌中這枚后璽便是虎符！宿衛立刻依令封鎖北門、徹查出入！"],"練":["親點校場！這群新兵太過鬆懈，今日先斬三個偷懶耍滑的什長立威，剩下的人加倍操練！","把新募的精壯全編入長樂宮直屬營，由本宮親信校尉督練，只認椒房殿號令！"],"土":["大興土木重修長樂宮與椒房殿，城裡最好的青石、良木與工匠全給本宮調過來！","殿宇不夠森嚴氣派，如何鎮得住滿朝文武？外牆緩兩日，先替本宮把九階高臺砌起來！"],"祭":["今日大祭由本宮親自主持！天地神明與全城軍民都得看清楚，誰才是這座燈塔真正的女主人！","省去那些酸儒繁文縟節，拉幾個叛逆首級祭天，比三牲六畜更能鎮住黑霧！"],"刑":["開掖庭獄！把那個嚼舌根的宮婢和貪墨倉吏拖進暗室，先髡髮烙印，再讓他們嚐嚐「人彘」的滋味！","不見血，這群賤奴永遠記不住規矩——今晚暗室的慘叫不許停，讓鄰近各殿都聽清楚！"],"官":["朝中那幾個空缺不必報書房了，直接把本宮外戚派親信與呂氏門客全安插進去！","前朝那些只會咬文嚼字的舊臣全貶去苦寒分城，換上只認椒房殿臉色的新官！"]}},"power":{"diaochan":{"veto":["（搖著團扇，眼波一轉）你要處置我？內廷和前朝好幾個將軍都欠我的情，這道旨你發得出去，也推不下去。","（聲音柔，一步不退）董卓和呂布當年都拿我沒辦法。你今天真要罰我，先想清楚後果。","你氣頭上下的旨，我先替你壓下了，免得寒了諸將的心——也免得你後悔。"],"rise":"（站在閉月花廊上俯看燈塔，神色從容）女人從來不是棋子。如今這盤棋，換我執子。","regent":"（珠簾後身影婀娜，聲音卻冷）你倦了，就由我在簾後管著前朝的文臣武將。這座城，一滴水也漏不出去。","fall":"（摸著髮簪淡淡一笑）權勢像月亮，有圓有缺。只要男人還有慾望，我隨時能再起一局。","ev":[{"t":"閉月調停・諸將唯命","l":[[null,"兩個手握重兵的猛將為軍功在金殿上拔刀，你喝止都沒用。貂蟬從珠簾後走出來，走到兩人中間，一人耳邊說了一句話。兩人臉色同時發白，收刀，單膝跪下向她領命。後來才知道，她說的是兩人各自私通過誰的妻子。"],[null,"（回頭對你一笑）武將性子烈，硬壓壓不住，得捏他們的軟處。往後軍中調和，交給我，你省心。"]],"c":[["欣賞她的手腕，把軍中調和與犒賞大權交給她",null,"{a}：「謝夫君。三軍會怕你，也會怕我。」"],["覺得皇權受威脅，當眾冷臉斥責兩將，收回她插手軍務的權",null,"{a}：「（笑容一收）我替你平了內鬨，你倒防起我來了？」"],["笑著嘉獎，暗中改由自己親信負責下次犒軍",null,"{a}：「夫君心細。我懂自己的分寸——也懂你的。」"]],"after":"以柔克剛到了頭，比鐵血殺伐更讓君王心驚。"},{"t":"連環離間・智破敵盟","l":[[null,"城外兩支敵軍結盟，準備合圍。貂蟬調動她的耳目，送一個女人進敵軍主帥帳中，再讓副將撞見。三天後，主帥把副將全家剝皮吊在營門，副將帶兵夜襲主帥，兩軍自相殘殺，屍體堆滿了河灘。"],[null,"（擦掉額角的汗，眼神傲得發亮）禍平了。我用一個女人，換了他們兩萬條命。這樣，你還敢把我當成尋常深宮婦人？"]],"c":[["大笑著把她抱起來重賞，准她參與中樞機密議政",null,"{a}：「跟你並肩下棋，才不枉我這輩子。」"],["厚賞珠寶位分，但不讓她碰前朝機密",null,"{a}：「（輕嘆）到頭來，還是只要我當個花瓶。」"],["怕她的連環計太可怕，趁機斷她與前朝將領的聯繫",null,"{a}：「鳥盡弓藏？夫君，聰明人不這樣做。董卓也想過防我。」"]],"after":"全城都知道了：閉月美人那張笑臉後面，藏著能讓千軍自相殘殺的刀。"}]},"lvzhi":{"veto":["（冷笑將你的處置詔書撕成兩半，隨手丟進炭盆）天運者，你如今連南北軍都調不動一半，也敢下旨處置本宮？","想罰本宮？先問問殿外三千長樂玄甲衛手裡的戟答不答應！","這道旨意太荒唐，本宮替你壓下了——回寢殿醒醒酒，冷靜了再跟本宮談！"],"rise":"（負手立於未央高階俯視伏地百官）從今日起，這座燈塔的前朝與後宮，凡事皆須先看本宮長樂宮的臉色！","regent":"（珠簾緩緩垂落，后璽重重壓上玉案）天運者既無力獨斷乾坤，便由本宮臨朝稱制——百官有事，直奏簾後！","fall":"（雖被收繳兵符，雙眸仍陰毒如蛇）虎落平陽罷了……你今日既不殺本宮，來日我必十倍血債討還！","ev":[{"t":"椒房代朝・百官只認后璽","l":[[null,"今日早朝，你因微恙晚到半個時辰，踏入正殿時卻見文武百官早已齊刷刷跪在珠簾前，呂雉端坐高臺之上，竟已代你批完半數軍國章疏。"],[null,"（連眼皮都沒抬，淡聲道）夫君既身子不適，便在旁歇著吧。今日的糧餉調撥與邊將任免，本宮已經蓋上后璽發下去了。"],[null,"「妳連問都沒問過我一聲？」"]],"c":[["冷笑認可她的鐵腕，順勢將前朝政務全交由她垂簾處置",null,"{a}：「這才識大體。放心，這座江山攥在本宮手裡，只會比在你手裡更穩。」"],["當眾拍案喝令收回后旨，強硬奪回批紅大權",null,"{a}：「（冷眸森然）當著滿朝文武落本宮的臉？很好，咱們走著瞧。」"],["表面稱讚她辛勞，暗中命親信記下今日只向珠簾叩首的官員名單",null,"{a}：「（意味深長地瞥你一眼）夫君這份隱忍城府，倒長進了不少。」"]],"after":"正殿之上的君座與珠簾，從此分庭抗禮、寸土必爭。"},{"t":"鐵腕鎮叛・以血護城","l":[[null,"城外黑霧暴動之際，城內兩名手握兵權的舊將竟趁亂串聯叛變，眼看就要奪下北門！千鈞一髮之際，呂雉竟比你更快一步——她直接動用長樂宮私養的死士與酷吏，一夜之間將兩名叛將滿門老小盡數屠絕，親手提著兩顆滴血的首級擲在正殿青磚上。"],[null,"（拿絲帕慢條斯理擦去指尖血跡，冷笑抬眸）若等你慢慢查證講仁義，這座城天亮前就易主了。如今叛亂已平，這份護城大功，夫君打算拿什麼賞本宮？"]],"c":[["大笑封賞外戚一派，默許她繼續擴張長樂宮兵權",null,"{a}：「這才像個成大事的君王！有本宮替你執刀，誰也翻不了天。」"],["嘉獎她護城有功，卻趁機收編她私養的死士歸入南北軍",null,"{a}：「（冷笑一聲）過河拆橋？好，這筆帳本宮記在心裡了。」"],["冷聲斥責她未經旨意擅殺大將，命她閉門思過",null,"{a}：「救了你的江山還反咬一口？天運者，你真是糊塗透頂！」"]],"after":"她用最血腥的手段替你斬斷一場滅城之禍，卻也讓滿朝文武對長樂宮的恐懼深入骨髓。"}]}},"cycle":{"diaochan":{"p0":["（按著小腹，眉頭擰著，臉色白得透青）月事來了，疼得我連腰都直不起來，舞步更別提。","手腳冰得像死人……你不嫌，就替我溫一壺薑茶，坐著陪我說話。","（虛虛地笑）平日要對前朝後宮笑臉迎人，就這幾天能光明正大地偷懶，誰來我都不見——你除外。"],"p1":["（臉頰泛著桃紅，眼裡水光晃蕩，一抬手一轉身都帶著香風）這幾天身子輕得要飄起來，月光照著都覺得燙。","新排了一支《閉月驚鴻》，只跳給你看。今晚敢爽約，我就去你書房跳。","（貼進你懷裡，嘴唇擦過你的耳朵）這幾天特別想你身上的熱。今晚留下來。"],"p2":["（嘆氣，眉心擰著）這幾天心煩得要命，看落花都想哭，看人都想殺。","嘴裡淡得沒味，想吃江南的酸梅糕，還有熱騰騰的桂花酒釀圓子——現在就要。","（團扇半遮臉，語氣衝）這幾天你多哄我。我現在一點就著，誰靠你近一步，我都想撕了她。"],"ev":[{"phase":null,"t":"花廊畏寒・溫茶解痛","l":[[null,"經期的貂蟬疼得蜷在閉月花廊的暖榻上，薄毯底下的手死死按著小腹，額頭全是冷汗，平日勾人的眼睛此刻只剩一層水霧。"],[null,"（看見你，勉強扯出一個笑）你來了……今天跳不了舞給你看，只能讓你陪我這隻病貓坐坐。"]],"c":[["把薄毯換成厚錦被，親手端來滾燙的紅糖薑棗茶，一口一口餵她",null,"{a}：「（小口喝著，臉頰慢慢紅了）你這樣，比什麼名醫的藥都管用。」"],["坐在榻邊替她揉腰腹，壓著聲講前朝的醜事逗她",null,"{a}：「（笑出聲又疼得抽氣）討厭，笑得肚子扯著疼……可心裡是暖的。」"],["交代宮女照顧她，自己趕去處理公事",null,"{a}：「（垂下眼）……正事要緊。我自己躺著，死不了。」"]],"after":"卸下那張完美的面具，她這點依賴，比什麼媚態都勾人。"},{"phase":null,"t":"閉月驚鴻・傾城之夜","l":[[null,"排卵期的貂蟬美得讓人不敢多看。月色正好，她在花廊裡為你獨舞，薄紗被汗浸透貼在身上，每一個旋身都朝你拋來一眼，眼裡全是渴。"],[null,"（舞罷喘著氣跌進你懷裡，臉紅到耳根，手指勾開你的衣帶）今晚月亮這麼好，我身子這麼燙……別想前朝了，好不好？"]],"c":[["吻住她微張的嘴，抱進內室",null,"{a}：「（勾住你的脖子，聲音發顫）今晚你只是我的……」燭火被她一袖子掃滅。天亮時宮婢在門外等了一個時辰，聽見裡頭還有動靜，紅著臉退了下去。"],["笑讚她舞姿絕世，月下共飲一杯再入帳",null,"{a}：「跟你在月下喝酒……就是我想了兩輩子的日子。」"],["誇完舞姿，順口談起明天怎麼拉攏武將",null,"{a}：「（推了你一把，咬著牙笑）這種時候還談權謀，你是木頭嗎？」"]],"after":"天亮後花廊的軟榻上散著扯斷的珠串和一條撕破的薄紗。打掃的宮婢一聲不吭收走了，當天就被貂蟬賞了一對金鐲——封口費。"},{"phase":null,"t":"經前敏感・酸梅解愁","l":[[null,"經前的貂蟬心浮氣躁。今天看見你和幾個女將說笑，回殿後一個人對著鏡子坐了一下午，把一把象牙梳掰成了兩截。"],[null,"（聲音酸，又帶著少見的脆）我這兩天老是胡思亂想……等我老了，你還會這樣看我嗎？還是跟那些女將一樣，說笑幾句就忘了？"]],"c":[["從背後抱住她，掏出剛買的酸梅糕：「我要的是妳這個人，不是這張皮」",{"love":null,"food":null,"mood":null},"{a}：「（咬一口酸梅糕，眼淚還掛著就笑了）嘴真甜……我這兩天真是瘋了。」"],["替她梳頭，保證這幾天天天來花廊陪她吃晚飯",{"love":null,"mood":null},"{a}：「有你這句，心裡那根刺就拔了。」"],["笑她堂堂智謀美人也學小丫頭吃乾醋",{"love":null,"mood":null},"{a}：「（別過臉冷哼）我吃醋，在你眼裡就這麼可笑？那幾個女將，你最好別再讓我看見。」"]],"after":"再精的女人，經前那幾天也只想要最笨、最直白的偏愛。給不了的，她會記一輩子。"}]},"lvzhi":{"p0":["（按著微微絞痛的小腹，指尖冰涼卻依舊端坐批閱竹簡）這點月事寒痛算什麼？當年逃難被項羽擄進楚營，比這痛上百倍的日子本宮都熬過來了。","把這碗放涼的茶潑了，叫膳房換一碗滾燙的老薑赤糖湯來——哪個宮婢敢多嘴嚼舌說本宮臉色發青，直接掌嘴二十。","這幾日身子見紅發沉、腰腹墜痛，別拿後宮那些雞毛蒜皮的爛事來煩本宮，否則我可沒平日的好耐心。"],"p1":["（兩頰透出罕見的潮紅，眼波滾燙如酒，鬆開一寸衣襟露出飽滿微脹的雙乳）這兩日血氣正旺、胞宮溫熱，身子裡像燒著一把火——今晚別去別殿了，宿在椒房殿罷。","（手指勾住你的衣帶，嗓音低啞而霸道）這兩日正是容易結珠受孕的時候。本宮要替你生下最尊貴的嫡長骨血，今晚夫君休想敷衍了事。","氣血充盈得很，連腰臀都透著熱意。今夜先把前朝章疏撂下，好好伺候本宮這副身子。"],"p2":["（煩躁地將手中朱筆咔嚓折斷，胸口起伏不定）這幾日雙乳脹痛、心火直衝腦門，偏偏前朝那群老東西還天天上廢話章疏！","別在本宮耳邊提{b}那張討厭的臉！這兩日我火氣大得想殺人，誰撞到槍口上誰就去永巷躺著。","（揉著發脹的太陽穴冷哼）莫名想喝滾燙酸辣的羹湯……叫膳房半刻鐘內端上來，慢了一步統統罰俸！"],"ev":[{"phase":null,"t":"寒痛批紅・鐵血不退","l":[[null,"呂雉正值經期，小腹絞痛得額頭沁出細密冷汗，玄色中衣裡貼著暖袋，卻依然面無表情地坐在炭盆旁批閱軍報，甚至因腹痛難忍而下令將一名寫錯字的書吏重杖三十。"],[null,"（指節發白地按著小腹，冷聲道）區區月事見紅也想叫本宮停筆？天運者，你未免太小看大漢高后了。"]],"c":[["強行奪過她手裡的朱筆，將她抱上暖榻，隔著裡衣以溫熱掌心替她慢慢捂揉小腹",null,"{a}：「（身子一僵，隨即鬆開緊鎖的眉頭冷哼）……這世上也就你敢這樣管本宮。罷了，歇半個時辰。」"],["稱讚她鐵血剛毅，順手接過剩餘的軍報替她批完",null,"{a}：「有夫君搭手，這幾卷臭帳倒是清得快多了。」"]],"after":"椒房殿的銀炭燒得極旺，總算替她驅散了幾分滲進骨縫裡的寒痛。"},{"phase":null,"t":"椒房夜邀・共謀嫡嗣","l":[[null,"排卵期的呂雉面若桃花、神采逼人，深夜遣退所有宮婢，只著一件薄軟絳紅中衣斜倚在暖榻上。酒氣與濃郁暖香混在一起，豐乳與圓臀在燭火下曲線畢露，她望著你的眼神熾熱而露骨，絲毫不掩身體裡的渴求與孕嗣野心。"],[null,"（伸手將你拽到榻邊，呼吸滾燙地噴在你耳畔）這兩日身子最熱、花露都快藏不住了……夫君，別再端著架子，今晚給本宮一個能承繼江山的孩子。"]],"c":[["大笑吹熄床前銅燈，反手將她壓進錦被「如高后所願，今晚哪兒也不去」",null,"{a}：「（雙臂死死勾住你的脖頸，低喘著笑出聲）這才配做我呂雉的夫君……」帳幔落下後徹夜未歇，次日宮婢入殿收拾被褥時見榻單濕透、滿地凌亂衣帶，連頭都不敢抬。"],["笑著陪她共飲暖酒、輕撫她發燙的腰肢，卻巧妙避開了過於沉重的儲君話題",null,"{a}：「滑頭……不過今晚人既進了椒房殿，不把本宮伺候到身子發軟，休想下床。」"]],"after":"權力與血脈的交纏，在那一夜化作了最赤裸而滾燙的佔有。"},{"phase":null,"t":"經前肅殺・怒斥六宮","l":[[null,"經前期的呂雉胸悶煩躁到了極點，今日晨起定省時，僅因兩名妃嬪低頭竊竊私語了半句，她竟當場拍碎玉案、喝令宿衛拔刀，把滿殿夫人訓斥得臉色煞白、大氣不敢喘。"],[null,"（煩躁地按著太陽穴，雙眸泛紅）一個個七嘴八舌吵得像市井野鴨，教本宮頭疼欲裂！"]],"c":[["揮退眾人，親手替她按揉眉心並端上一碗滾燙的酸辣羊肉羹",{"love":null,"mood":null},"{a}：「（喝了一口熱羹，胸口鬱氣總算順了幾分）……還是你懂本宮這股無名邪火。」"],["勸她莫為一點小事把六宮嚇得人心惶惶，反被她冷眼頂了回去",{"love":null,"mood":null},"{a}：「連你也嫌本宮脾氣暴、不討喜？滾去哄你的溫順小美人吧！」"]],"after":"那一碗滾燙的酸辣羹，暫時壓住了椒房殿即將見血的雷霆。"}]}},"pbuild":{"diaochan":{"n":null,"where":[null,null,null],"tile":null,"d":"花海高坡上一座飛簷涼亭。月光一穿透黑霧落下來，亭裡焚香拜月的身影就讓全城的人停下腳步看——看久了的，有幾個再沒回家。","eff":null,"self":{"love":null,"mood":null},"ask":"（望著被黑霧吞掉的月亮）這長夜太黑太冷了。你在花坡上替我修一座拜月亭，每逢月圓，我在那裡替你和這座城焚香。在王允府裡，我也是這樣拜月的。","done":"（踩上白玉台階，回頭一笑）月光落在飛簷上，跟夢一樣。從今往後，這是我們兩個人的地方——誰敢上來，我讓他滾下去。","max":"（漫天花雨裡展開舞袖）拜月亭成了全城最美的地方。只要亭子在、月亮在，我就陪你把這長夜熬過去。","visit":[[[null,"夜裡難得有一縷月光穿過黑霧，落在拜月亭上。貂蟬正在焚香，只披一件素紗，側臉白得發光。"],[null,"（聽見腳步聲回頭）忙完了？我剛替你對月亮許了個願。"],[null,"「許了什麼？」"],[null,"（靠進你懷裡，手指在你胸口畫圈）黑霧早點散，你平平安安……還有，這輩子不再當誰的棋子，只當你一個人的女人。"]],[[null,"晚風吹過花坡。貂蟬在亭裡替你斟桂花茶，團扇一搖，滿亭都是她身上的香。"],[null,"從前在王允府裡拜月，心裡全是國仇、算計，算董卓幾時死、呂布幾時動手。現在拜月，心裡只剩你。"],[null,"「那些就留在三國，這裡只有我們。」"],[null,"（眼波一軟，指尖慢慢描過你的眉眼）嗯。有你在，這亭子就是仙境。"]],[[null,"深夜露重。貂蟬放下四面紗帳擋風，點一盞暖紅燈籠，亭裡一下子只剩你們兩個人的影子。"],[null,"（紅著臉替你披上外袍，手卻沒拿開）夜深了，風大，你還不回去？"],[null,"「月下看美人，怎麼看都不夠。」"],[null,"（笑著拉你進紗帳，吹熄燈籠）看不夠，就別看了。"]]],"ev":[{"pos":null,"t":"拜月安軍・化干戈為玉帛","l":[[null,"兩個為防務功勞結仇的猛將差點在街上拔刀。貂蟬在拜月亭設宴，一支舞、三杯酒，席間各自在兩人耳邊說了幾句。兩人當場摔杯結拜，散席時臉都是白的。"],[null,"（福身一笑）武將最要面子。在亭子裡喝兩杯、讓他們知道我手裡有什麼，比朝堂上各打五十大板管用。"]],"c":[["大喜，嘉獎她調和三軍，重賞拜月亭珍稀香木與茶具",null,"貂蟬：「謝夫君。三軍齊心，黑霧就不算什麼。」"],["抱住她：「這座拜月亭，是我的福地」",null,"貂蟬：「能替你擺平這些，我比收什麼都高興。」"],["順勢邀兩個和好的猛將明天共議破敵，士氣大振",null,"貂蟬：「你果然會抓時機。」"]],"after":"拜月亭不只是風雅地方，也成了前朝那些人最怕被請去的地方。"},{"pos":null,"t":"亭下蜚語・醋海暗湧","l":[[null,"一個仰慕貂蟬的年輕武將喝醉了，半夜跑到拜月亭下的花坡高聲吟詩示愛，被侍衛拖走。第二天，後宮幾位夫人就到處說貂蟬勾引外將，還說那武將的腰帶在亭子裡找到了。"],[null,"（眉頭一皺，又委屈又冷）我整夜在亭裡抄經，連那人長什麼樣都不知道。不信，去問值夜的侍衛。那條腰帶是誰放的，我也會查出來。"]],"c":[["毫不動搖地護她，重罰醉酒武將和造謠的夫人",null,"貂蟬：「（眼裡一熱）謝你信我。那幾個造謠的——我會讓她們知道，嘴賤要付什麼價。」"],["相信她清白，卻吃醋下令任何武將不准靠近拜月亭百步",null,"貂蟬：「（噗哧一笑）你吃起醋來還挺可愛。都聽你的。」"],["起了疑心，冷著臉盤問她平日是不是跟武將太近",{"love":null,"mood":null},"貂蟬：「（臉色徹底冷了）連你也信？好，我閉門不出。你以後也別來。」"]],"after":"三天後，那個醉酒的武將被發現淹死在城外溝渠裡，造謠的夫人殿裡起了一場小火，燒掉了她半張臉。沒人查得到是誰做的。"}],"envy":"（搖著團扇笑，眼底一片冷）你替{b}蓋新宮殿了？拜月亭的月亮再好，也比不上新人新景。","ruin":"（看著拜月亭塌成一地斷木碎瓦，眼淚無聲往下掉，手卻攥緊了）連一處拜月的地方都守不住……這亂世，容不下一點溫柔。那就別溫柔了。"},"lvzhi":{"n":null,"where":[null,null],"tile":null,"d":"飛簷玄瓦、高臺重闕的森嚴宮殿。燈塔微光照不透九重珠簾，唯有黑霧夜色下的冷酷政令與鐘室血影由此傳遍四方。","eff":null,"self":null,"ask":"（冷眸掃過殿外翻湧的黑霧）偏殿太過逼仄，壓不住這滿城野心。替本宮起一座「長樂宮」吧——當年我便是在長樂宮鐘室斬了韓信，唯有夠深夠冷的宮牆，才鎮得住前朝這群狼。","done":"（指尖撫過冰涼的玄石宮柱，唇角緩緩勾起）不錯，這座長樂宮的威壓，才配得上大漢高后。從今日起，誰敢在燈塔下造次，本宮便在這裡替你收尾。","max":"（端坐九階高臺俯視全城，氣場森然如鐵）長樂宮既成極盛，這座孤城的生殺、糧稅與律法，便徹底牢握在你我夫妻掌中了。","visit":[[[null,"夜霧沉沉，長樂宮內只點著兩盞青銅長明燈，呂雉正對著一疊密報冷冷批紅，深衣領口因夜深微鬆，露出一截白皙頸項。"],[null,"（頭也不抬）這麼晚還踏進長樂宮，是前朝哪個老東西又讓你心煩了？"],[null,"「不是公事，只是想來看看妳。」"],[null,"（擱下朱筆，抬眼盯了你半晌，忽然起身替你解開外甲，指尖帶著酒氣與暖意）……算你還懂事。外頭霧寒，進暖帳說話吧。"]],[[null,"長樂宮後苑的幽暗長廊裡，呂雉正拿著一把鋒利鐵剪，慢條斯理地修剪一株在黑霧邊緣開得格外妖異的玄色牡丹。"],[null,"（鐵剪咔嚓一聲剪斷多餘枝葉，花汁濺在她手背上）治國跟剪花一樣，不狠心把旁枝末節全剪乾淨，主幹遲早被吸乾。"],[null,"「妳這雙手，剪花和殺人一樣穩。」"],[null,"（回眸冷豔一笑，將帶著冷香的指尖搭上你的手背）那夫君可得站穩了，別成了本宮剪刀下的旁枝。"]],[[null,"暴雨拍打著長樂宮玄瓦，殿內薰香濃烈得近乎醉人。呂雉只披一件薄錦外袍，親自替你斟滿一杯滾燙的關中虎骨烈酒，豐腴腰身倚在案側。"],[null,"（將酒盞送到你唇邊，眼底暗火翻湧）滿城上下都怕本宮這座長樂宮，怕得連夜裡路過都發抖，唯獨你敢一個人推門進來。"],[null,"「怕妳的話，當初就不會替妳起這座宮殿。」"],[null,"（眼底寒冰罕見地徹底融開，貼近你耳畔低啞開口，手指順勢解開你的腰帶）……這句話，本宮記下了。今晚不准走，燈也不必留了。"]]],"ev":[{"pos":null,"t":"長樂密審・先發制叛","l":[[null,"呂雉利用長樂宮四通八達的暗廊與遍布全城的耳目，提前截獲了一批企圖在霧潮夜裡裡應外合的叛將密信，一夜之間動用死士將所有內奸全數鎖進宮底鐘室暗牢！"],[null,"（將沾著血與蠟封的密信推上案頭）若等前朝按部就班查證，城門早破了。人全在長樂宮底下綁著，是要砍頭還是剁成肉醬，天運者一句話。"]],"c":[["大笑讚她鐵腕護城，將叛將家產全數充公並賞她三成",null,"呂雉：「這才像個成大事的君王。有長樂宮在，誰也翻不了天。」"],["按律嚴懲主謀，並公開嘉獎長樂宮肅反有功",null,"呂雉：「名正言順地立威，倒也省了本宮不少口舌。」"],["接管審訊權，私下叮囑她下次動手前先知會一聲",null,"呂雉：「（冷笑）替你保住命還要講程序？行，下回我先派人敲你書房門。」"]],"after":"長樂宮鐘室的威名一夜傳遍前朝，再無人敢生半分二心。"},{"pos":null,"t":"長樂私刑・慘叫驚宮","l":[[null,"深夜巡衛密報：長樂宮地底暗室傳出令人毛骨悚然的淒厲慘叫，呂雉竟私自將兩名曾背後譏諷她與審食其舊事的前朝幕僚拖進宮中，拔舌斷筋、動用「人彘」酷刑，血腥味順著石縫飄出，嚇得鄰近宮殿人人自危！"],[null,"（漫不經心地用熱巾擦拭手上的血水，神色淡漠）兩條管不住臭嘴的賤狗，本宮在自己宮裡替他們長點記性，也值得你半夜跑來興師問罪？"]],"c":[["冷血默許「死在長樂宮裡的人，自然都是該死的」",null,"呂雉：「哈哈，還是夫君懂我。放心，血跡天亮前會刷乾淨，不污你的眼。」"],["震怒下令立刻停刑救人，嚴厲斥責她濫施私刑",null,"呂雉：「（冷眸森然）為了兩條嚼舌根的狗跟我翻臉？好得很，你且護著他們吧。」"],["命她把人交給廷尉明正典刑，別在後宮裡弄得血腥沖天",null,"呂雉：「嫌這兒太髒？罷了，丟進廷尉大牢也是一樣的死法。」"]],"after":"長樂宮高牆地底的秘密，從此成為這座燈塔最令人膽寒的忌諱。"}],"envy":"（冷笑捏碎手中青玉茶盞，碎瓷扎進掌心也不皺眉）替{b}大興土木？天運者，你可別忘了，這座城裡誰才是真正替你鎮住江山的女人！","ruin":"（盯著長樂宮化作一片焦土瓦礫，雙目陰毒如蛇）好啊……拆了本宮的長樂宮？總有一天，我會拿這座城裡所有仇人的血，一磚一瓦重新砌起來！"}}};
function mg(t,s){if(!t||typeof t!=='object')return;for(const k in s){const v=s[k];if(v==null)continue;if(!(k in t))continue;const o=t[k];if(typeof v==='string'){if(typeof o==='string')t[k]=v}else if(typeof v==='object'&&o&&typeof o==='object'&&Array.isArray(v)===Array.isArray(o))mg(o,v)}}
if(root&&typeof root==='object'){root.GD=root.GD||{};mg(root.GD,D)}
if(typeof module!=='undefined'&&module.exports)module.exports={D,apply:function(G){mg(G,D);return G}};
})(typeof window!=='undefined'?window:null);
